def is_windows():
    return sys.platform.startswith('win')
def is_admin():
    try:
        return ctypes.windll.shell32.IsUserAnAdmin()
    except Exception:
        return False
def _check_registry_odbc_17():
    if not winreg:
        return False
    keys = [winreg.HKEY_LOCAL_MACHINE]
    subkey = r"SOFTWARE\ODBC\ODBCINST.INI\ODBC Drivers"
    for view in (0, winreg.KEY_WOW64_64KEY, winreg.KEY_WOW64_32KEY):
        try:
            key = winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE, subkey, 0, winreg.KEY_READ | view)
            i = 0
            while True:
                try:
                    name, val, _ = winreg.EnumValue(key, i)
                    if name and 'ODBC Driver 17 for SQL Server' in name:
                        return True
                    i += 1
                except OSError:
                    break
        except Exception:
            continue
    return False
def check_odbc17_installed():
    try:
        return _check_registry_odbc_17()
    except Exception:
        return False
def check_vc_redist_installed():
    try:
        windir = os.environ.get('WINDIR', r'C:\Windows')
        candidates = [os.path.join(windir, 'System32', 'msvcp140.dll'),
                      os.path.join(windir, 'SysWOW64', 'msvcp140.dll')]
        for p in candidates:
            if os.path.exists(p):
                return True
    except Exception:
        pass
    return False
def get_resource_path(filename):
    """
    Resuelve la ruta de un archivo de recurso.
    Funciona tanto para scripts como para .exe de PyInstaller.
    """
    if getattr(sys, 'frozen', False):
        base_path = sys._MEIPASS
    else:
        base_path = os.path.dirname(os.path.abspath(__file__))
    resource_path = os.path.join(base_path, filename)
    if os.path.exists(resource_path):
        return resource_path
    if os.path.exists(filename):
        return filename
    if getattr(sys, 'frozen', False):
        exe_dir = os.path.dirname(sys.executable)
        exe_path = os.path.join(exe_dir, filename)
        if os.path.exists(exe_path):
            return exe_path
        internal_path = os.path.join(exe_dir, '_internal', filename)
        if os.path.exists(internal_path):
            return internal_path
    return resource_path
def find_local_installer(candidates):
    paths = []
    if getattr(sys, 'frozen', False):
        meipass = getattr(sys, '_MEIPASS', None)
        if meipass:
            paths.append(meipass)
        paths.append(os.path.dirname(sys.executable))
    else:
        paths.append(os.getcwd())
        paths.append(os.path.dirname(__file__))
    try:
        if EXTERNAL_DEPS_DIR:
            paths.insert(0, EXTERNAL_DEPS_DIR)
    except Exception:
        pass
    seen = set()
    for base in paths:
        try:
            for name in candidates:
                candidate = os.path.join(base, name)
                if os.path.exists(candidate) and candidate not in seen:
                    seen.add(candidate)
                    return candidate
        except Exception:
            continue
    return None
def _run_msi(msi_path):
    try:
        subprocess.check_call(['msiexec', '/i', msi_path, '/qn', '/norestart'])
        return True
    except Exception as e:
        log_debug(f"Error instalando MSI {msi_path}: {e}")
        return False
def _run_exe(exe_path):
    for args in ([exe_path, '/install', '/quiet', '/norestart'],
                 [exe_path, '/quiet', '/norestart'],
                 [exe_path, '/S'],
                 [exe_path, '/silent']):
        try:
            subprocess.check_call(args)
            return True
        except Exception:
            continue
    return False
def download_file(url, dest, timeout=30):
    try:
        log_debug(f'Descargando {url} -> {dest}')
        with urllib.request.urlopen(url, timeout=timeout) as resp:
            if resp.status != 200:
                return False
            data = resp.read()
            if not data:
                return False
            with open(dest, 'wb') as f:
                f.write(data)
        return True
    except Exception as e:
        log_debug(f'Error descargando {url}: {e}')
        return False
def ensure_system_dependencies():
    if not is_windows():
        return True
    missing = []
    if not check_vc_redist_installed():
        missing.append('vc')
    if not missing:
        return True
    if '--_install_deps' in sys.argv:
        succeeded = True
        if 'odbc' in missing:
            odbc_candidates = ['msodbcsql.msi', 'msodbcsql17.msi', 'msodbcsql-17.msi', 'msodbcsql-17.6.1.msi']
            odbc_inst = find_local_installer(odbc_candidates)
            if odbc_inst:
                succeeded &= _run_msi(odbc_inst)
            else:
                succeeded = False
        if 'vc' in missing:
            vc_candidates = ['vc_redist.x64.exe', 'vc_redist_2015-2019_x64.exe', 'vc_redist.x64_2015.exe']
            vc_inst = find_local_installer(vc_candidates)
            if vc_inst:
                succeeded &= _run_exe(vc_inst)
            else:
                succeeded = False
        if succeeded:
            messagebox.showinfo('Instalación', 'Dependencias instaladas correctamente. Reinicie la aplicación.')
            return True
        else:
            messagebox.showwarning('Instalación', 'No se encontraron instaladores locales o la instalación falló')
            webbrowser.open('https://learn.microsoft.com/sql/connect/odbc/download-odbc-driver-for-sql-server')
            return False
    try:
        log_debug(f'Iniciando instalación automática de dependencias faltantes: {missing}')
        if not is_admin():
            log_debug('Solicitando permisos de administrador...')
            ctypes.windll.shell32.ShellExecuteW(None, 'runas', sys.executable, '--_install_deps', None, 1)
            sys.exit(0)
        else:
            succeeded = True
            if 'odbc' in missing:
                odbc_candidates = ['msodbcsql.msi', 'msodbcsql17.msi', 'msodbcsql-17.msi', 'msodbcsql-17.6.1.msi']
                odbc_inst = find_local_installer(odbc_candidates)
                if odbc_inst:
                    log_debug(f'Instalando ODBC desde: {odbc_inst}')
                    succeeded &= _run_msi(odbc_inst)
                else:
                    log_debug('No se encontró instalador MSI de ODBC')
                    succeeded = False
            if 'vc' in missing:
                vc_candidates = ['vc_redist.x64.exe', 'vc_redist_2015-2019_x64.exe', 'vc_redist.x64_2015.exe']
                vc_inst = find_local_installer(vc_candidates)
                if vc_inst:
                    log_debug(f'Instalando Visual C++ desde: {vc_inst}')
                    succeeded &= _run_exe(vc_inst)
                else:
                    log_debug('No se encontró instalador de Visual C++')
                    succeeded = False
            if succeeded:
                log_debug('Instalación completada exitosamente')
                messagebox.showinfo('Instalación', 'Dependencias instaladas correctamente. Reinicie la aplicación.')
                return True
            else:
                log_debug('La instalación falló o no se encontraron instaladores')
                messagebox.showwarning('Instalación', 'No se encontraron instaladores locales o la instalación falló.')
                return False
    except Exception as e:
        log_debug(f'Error al intentar instalar dependencias automáticamente: {e}')
        return False
try:
    ensure_system_dependencies()
except Exception:
    pass
