LOG_FILE = os.path.join(LOGS_DIR, f'app_log_{datetime.now().strftime("%Y%m%d")}.json')

def log_debug(msg, contexto=None):
    """Registra mensajes de depuración como entradas JSON en el archivo de logs diario.
    Evita crear archivos de texto separados cuando se genera un .exe.
    """
    try:
        timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        entry = {
            'timestamp': timestamp,
            'tipo_accion': 'DEBUG',
            'mensaje': str(msg),
            'contexto': contexto if contexto is not None else {},
            'timestamp_ms': int(time.time() * 1000)
        }
        try:
            log_to_json(entry)
        except Exception:
            # en fallback, no escribir archivo .log; simplemente pasar
            pass
    except Exception:
        pass
def log_to_json(log_entry):
    """Registra logs en formato JSON para fácil análisis"""
    try:
        if os.path.exists(LOG_FILE):
            try:
                with open(LOG_FILE, 'r', encoding='utf-8') as f:
                    logs = json.load(f)
            except Exception:
                logs = []
        else:
            logs = []
        logs.append(log_entry)
        with open(LOG_FILE, 'w', encoding='utf-8') as f:
            json.dump(logs, f, ensure_ascii=False, indent=2)
    except Exception as e:
        log_debug(f"Error guardando log JSON: {e}")
def log_login(usuario_id, usuario_login, nombre_usuario, id_departamento, departamento_nombre, exitoso=True, razon=""):
    """Registra detalladamente logins exitosos y fallidos"""
    timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    log_entry = {
        'timestamp': timestamp,
        'tipo_accion': 'LOGIN',
        'exitoso': exitoso,
        'usuario_id': str(usuario_id) if usuario_id else 'DESCONOCIDO',
        'usuario_login': usuario_login,
        'nombre_usuario': nombre_usuario,
        'departamento_id': str(id_departamento) if id_departamento else '',
        'departamento_nombre': departamento_nombre,
        'razon_fallo': razon,
        'ip_address': 'LOCAL',
        'timestamp_ms': int(time.time() * 1000)
    }
    log_to_json(log_entry)
    log_debug(f"LOGIN: {usuario_login} ({'EXITOSO' if exitoso else 'FALLIDO'}) - {departamento_nombre}")
