def mostrar_notificacion_sistema(titulo, mensaje, duracion=5):
    """
    Muestra una notificación nativa de Windows.
    Args:
        titulo: Título de la notificación
        mensaje: Mensaje a mostrar
        duracion: Duración en segundos (default: 5)
    """
    if not NOTIFICATIONS_AVAILABLE or not is_windows():
        return False
    try:
        Notifier.notify(
            title=titulo,
            message=mensaje,
            timeout=duracion
        )
        return True
    except Exception as e:
        log_debug(f"Error mostrando notificación: {e}")
        return False
def notificar_cambio_estado_orden(numero_orden, estado_nuevo, usuario_nombre=None):
    """
    Muestra una notificación del sistema cuando cambia el estado de una orden.
    Args:
        numero_orden: Número de la orden
        estado_nuevo: Nuevo estado ('N'=Nueva, 'D'=Pendiente, 'P'=En Proceso, 'X'=Rechazado/Cancelado, 'C'=Cerrado)
        usuario_nombre: Nombre del usuario que hizo el cambio (opcional)
    """
    estado_info = {
        'N': {'nombre': 'Nueva', 'descripcion': 'Orden de trabajo nueva', 'emoji': '✨', 'color': 'INFO'},
        'D': {'nombre': 'Pendiente', 'descripcion': 'Pendiente de atención', 'emoji': '⏳', 'color': 'WARNING'},
        'P': {'nombre': 'En Proceso', 'descripcion': 'Trabajo en progreso', 'emoji': '🔄', 'color': 'INFO'},
        'X': {'nombre': 'Rechazada', 'descripcion': 'Orden cancelada/rechazada', 'emoji': '❌', 'color': 'WARNING'},
        'C': {'nombre': 'Cerrada', 'descripcion': 'Orden completada', 'emoji': '✅', 'color': 'SUCCESS'}
    }
    estado_display = estado_info.get((estado_nuevo or '').upper(), {})
    nombre_estado = estado_display.get('nombre', estado_nuevo)
    descripcion = estado_display.get('descripcion', '')
    emoji = estado_display.get('emoji', '●')
    titulo = f"{emoji} Orden #{numero_orden}"
    if usuario_nombre:
        mensaje = f"{nombre_estado}\n{descripcion}\nPor: {usuario_nombre}"
    else:
        mensaje = f"{nombre_estado}\n{descripcion}"
    mostrar_notificacion_sistema(titulo, mensaje, duracion=7)
def clean_cell(val):
    """Normaliza un valor de celda proveniente de la BD a string seguro.
    - None -> ''
    - bytes -> decodifica utf-8 con reemplazo
    - datetime -> formatea 'YYYY-MM-DD HH:MM:SS'
    - elimina espacios alrededor y caracteres invisibles comunes
    """
    try:
        if val is None:
            return ''
        if isinstance(val, datetime):
            return val.strftime('%Y-%m-%d %H:%M:%S')
        if isinstance(val, (bytes, bytearray)):
            try:
                s = val.decode('utf-8', errors='replace')
            except Exception:
                s = str(val)
            return s.strip()
        s = str(val)
        s = s.replace('\u00A0', ' ').replace('\x00', '')
        return s.strip()
    except Exception:
        try:
            return str(val)
        except Exception:
            return ''
