    """Crea un Label widget con estilo apropiado.
    editable=False: gris (información no modificable)
    editable=True: blanco (área de información ingresable visualmente)
    """
    bg_color = STYLE_EDITABLE_BG if editable else STYLE_READONLY_BG
    fg_color = STYLE_EDITABLE_FG if editable else STYLE_READONLY_FG
    label = tk.Label(parent,
                     text=text,
                     bg=bg_color,
                     fg=fg_color,
                     relief="solid",
                     bd=1 if editable else 0,
                     font=("Segoe UI", 10),
                     **kwargs)
    return label
