try:
    import pyodbc
    MSSQL_AVAILABLE = True
except Exception:
    MSSQL_AVAILABLE = False
class _MSSQLCursorWrapper:
    def __init__(self, cur):
        self._cur = cur
    def execute(self, operation, params=None, multi=False):
        try:
            if params:
                operation = operation.replace('%s', '?')
                return self._cur.execute(operation, params)
            else:
                return self._cur.execute(operation)
        except Exception:
            return self._cur.execute(operation, params) if params else self._cur.execute(operation)
    def fetchall(self):
        return self._cur.fetchall()
    def fetchone(self):
        return self._cur.fetchone()
    def close(self):
        try:
            return self._cur.close()
        except Exception:
            pass
    def __getattr__(self, name):
        return getattr(self._cur, name)
class _MSSQLConnWrapper:
    def __init__(self, conn):
        self._conn = conn
    def cursor(self):
        return _MSSQLCursorWrapper(self._conn.cursor())
    def commit(self):
        try:
            return self._conn.commit()
        except Exception:
            pass
    def close(self):
        try:
            return self._conn.close()
        except Exception:
            pass
    def rollback(self):
        try:
            return self._conn.rollback()
        except Exception:
            pass
    def __getattr__(self, name):
        return getattr(self._conn, name)
def get_conn(cfg=None):
    """Devuelve una conexión compatible con el API usado en el código.
    Siempre intenta conectar a SQL Server vía pyodbc (modo MSSQL).
    No hay fallback a MySQL/XAMPP: si `pyodbc` no está instalado se lanzará una excepción.
    """
    if not MSSQL_AVAILABLE:
        raise RuntimeError("pyodbc no está disponible. Instale pyodbc: pip install pyodbc and the ODBC driver for SQL Server.")
    conn_str = f"DRIVER={DB_DRIVER};SERVER={DB_SERVER};DATABASE={DB_NAME};UID={DB_USER};PWD={DB_PASSWORD}"
    c = pyodbc.connect(conn_str)
    return _MSSQLConnWrapper(c)
class _MysqlProxy:
    def connect(self, *args, **kwargs):
        return get_conn(kwargs if kwargs else None)
try:
    mysql = _MysqlProxy()
except Exception:
    pass
    def row_to_dict(cursor, row):
        try:
            if row is None:
                return None
            cols = []
            try:
                cols = [d[0] for d in cursor.description] if cursor.description else []
            except Exception:
                cols = []
            res = {}
            for i, val in enumerate(row):
                try:
                    col = cols[i] if i < len(cols) else str(i)
                except Exception:
                    col = str(i)
                try:
                    res[col] = val
                    res[col.upper()] = val
                    res[col.lower()] = val
                except Exception:
                    try:
                        res[str(i)] = val
                    except Exception:
                        pass
            return res
        except Exception:
            try:
                return dict()
            except Exception:
                return {}
    def fetchone_dict(cursor):
        r = cursor.fetchone()
        return row_to_dict(cursor, r) if r is not None else None
    def fetchall_dicts(cursor):
        rows = cursor.fetchall()
        return [row_to_dict(cursor, r) for r in rows]
    def table_columns(cursor, table_name):
        """Devuelve set de nombres de columnas para `table_name` intentando SQL Server e MySQL."""
        try:
            try:
                cursor.execute("SELECT COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = ?", (table_name,))
                cols = [r[0] for r in cursor.fetchall()]
                if cols:
                    return {c.upper() for c in cols}
            except Exception:
                pass
            try:
                cursor.execute(f"SHOW COLUMNS FROM {table_name}")
                cols = []
                for r in cursor.fetchall():
                    try:
                        if isinstance(r, (list, tuple)):
                            cols.append(r[0])
                        elif isinstance(r, dict):
                            cols.append(r.get('Field') or next(iter(r.keys())))
                        else:
                            cols.append(r[0])
                    except Exception:
                        continue
                return {c.upper() for c in cols if c}
            except Exception:
                return set()
        except Exception:
            return set()
ESTADO_MAPPING = {
    'N': 'Nueva',
    'D': 'Pendiente',
    'P': 'En Proceso',
    'X': 'Cancelado',
    'C': 'Cerrado'
}
def get_estado_display(codigo_estado):
    """Convierte un código de estado (N, P, X, C) a su nombre legible."""
    return ESTADO_MAPPING.get((codigo_estado or '').upper(), 'Desconocido')
def get_estado_tag(estado):
    """Devuelve una etiqueta de Treeview para el color del estado."""
    if estado is None:
        return 'estado_default'
    valor = str(estado).strip().lower()
    if valor == 'n' or 'nueva' in valor:
        return 'estado_nueva'
    if valor == 'c' or 'cerrad' in valor:
        return 'estado_cerrada'
    if valor == 'x' or 'cancel' in valor or 'rechaz' in valor:
        return 'estado_cancelada'
    if valor == 'd' or 'pendient' in valor:
        return 'estado_pendiente'
    if valor == 'p' or 'proceso' in valor:
        return 'estado_en_proceso'
    return 'estado_default'
def get_estado_codigo(nombre_estado):
    """Convierte un nombre de estado ('Nueva', 'Pendiente', 'Cancelado', 'Cerrado') a su código."""
    try:
        n = (nombre_estado or '').strip().lower()
        mapa = {
            'nueva': 'N',
            'nuevo': 'N',
            'pendiente': 'D',
            'en proceso': 'P',
            'proceso': 'P',
            'cancelado': 'X',
            'cancelada': 'X',
            'rechazado': 'X',
            'cerrado': 'C',
            'cerrada': 'C',
            'finalizado': 'C',
            'finalizada': 'C',
        }
        if n in mapa:
            return mapa[n]
        inverso = {v.lower(): k for k, v in ESTADO_MAPPING.items()}
        return inverso.get(n, '')
    except Exception:
        return ''

def get_fallas_estados(order_id, cfg):
    """Obtiene los estados de todas las fallas de una orden.
    Retorna una lista de tuplas (NOMBRE_FALLA, ESTADO_CODIGO).
    """
    fallas_estados = []
    try:
        conn = mysql.connect(**cfg)
        cur = conn.cursor()
        cur.execute("""
            SELECT COALESCE(f.NOMBRE_FALLA, 'Falla'), COALESCE(ofl.ESTADO, 'N')
            FROM ORDENES_FALLAS ofl
            LEFT JOIN FALLAS f ON ofl.ID_FALLA = f.ID_FALLA
            WHERE ofl.ID_ORDEN = %s
            ORDER BY ofl.ID_FALLA
        """, (order_id,))
        fallas_estados = cur.fetchall()
        cur.close()
        conn.close()
    except Exception:
        pass
    return fallas_estados

def get_estado_criticidad(estado_codigo):
    """Retorna la criticidad de un estado (menor = más crítico).
    Nueva: 1, Pendiente: 2, En Proceso: 3, Cancelado: 4, Cerrado: 5
    """
    codigo = (estado_codigo or 'N').upper().strip()
    criticidad_map = {
        'N': 1,  # Nueva - Más crítica
        'D': 2,  # Pendiente
        'P': 3,  # En Proceso
        'X': 4,  # Cancelado
        'C': 5   # Cerrado - Menos crítica
    }
    return criticidad_map.get(codigo, 5)

def get_color_tag_for_fallas(fallas_estados):
    """Determina el tag de color basado en el estado MÁS CRÍTICO de las fallas.
    Criticidad: Nueva(1) > Pendiente(2) > En Proceso(3) > Cancelado(4) > Cerrado(5)
    
    Retorna: (tag_color, texto_estado_mas_critico)
    """
    if not fallas_estados:
        return "estado_nueva", "Nueva"
    
    # Obtener el estado más crítico (menor número = más crítico)
    min_criticidad = min(get_estado_criticidad(est[1]) for est in fallas_estados)
    
    # Encontrar el código que corresponde a esta criticidad
    estado_critico = None
    for nombre, codigo in fallas_estados:
        if get_estado_criticidad(codigo) == min_criticidad:
            estado_critico = codigo
            break
    
    # Determinar tag de color basado en el estado MÁS CRÍTICO
    if not estado_critico:
        tag = "estado_nueva"
        texto = "Nueva"
    elif estado_critico.upper() == 'N':
        tag = "estado_nueva"
        texto = "Nueva"
    elif estado_critico.upper() == 'D':
        tag = "estado_pendiente"
        texto = "Pendiente"
    elif estado_critico.upper() == 'P':
        tag = "estado_en_proceso"
        texto = "En Proceso"
    elif estado_critico.upper() == 'C':
        tag = "estado_cerrada"
        texto = "Cerrado"
    elif estado_critico.upper() == 'X':
        tag = "estado_cancelada"
        texto = "Cancelado"
    else:
        tag = "estado_nueva"
        texto = "Nueva"
    
    return tag, texto


def convert_date_to_display_format(date_str):
    """Convierte YYYY-MM-DD, datetime object, o DD/MM/YYYY a DD/MM/YYYY HH:MM para mostrar (sin segundos)
    IMPORTANTE: Asegura que siempre muestra en formato DD/MM/YYYY (español)"""
    if not date_str:
        return ''
    try:
        from datetime import datetime
        
        # Si es un objeto datetime, convertirlo directamente
        if isinstance(date_str, datetime):
            return date_str.strftime('%d/%m/%Y %H:%M')
        
        # Si no es string, retornar vacío
        if not isinstance(date_str, str):
            return ''
            
        date_str = date_str.strip()
        # Normalizar formatos ISO con T y microsegundos
        if date_str.endswith('Z'):
            date_str = date_str[:-1]
        if 'T' in date_str and ' ' not in date_str:
            date_str = date_str.replace('T', ' ', 1)
        if '.' in date_str and date_str.count(':') >= 1:
            date_str = date_str.split('.', 1)[0]
        
        # Si ya está en formato DD/MM/YYYY, devolverlo tal cual (sin segundos)
        if '/' in date_str:
            # Remover segundos si los tiene
            if ' ' in date_str:
                fecha_parte, hora_parte = date_str.split(' ', 1)
                if ':' in hora_parte:
                    partes_hora = hora_parte.split(':')
                    # Tomar solo HH:MM
                    return f"{fecha_parte} {partes_hora[0]}:{partes_hora[1]}"
            return date_str
        
        # Intentar convertir desde YYYY-MM-DD HH:MM:SS
        try:
            dt = datetime.strptime(date_str, '%Y-%m-%d %H:%M:%S')
            return dt.strftime('%d/%m/%Y %H:%M')
        except Exception:
            pass
        
        # Intentar convertir desde YYYY-MM-DD HH:MM
        try:
            dt = datetime.strptime(date_str, '%Y-%m-%d %H:%M')
            return dt.strftime('%d/%m/%Y %H:%M')
        except Exception:
            pass
        
        # Intentar convertir desde YYYY-MM-DD
        try:
            dt = datetime.strptime(date_str, '%Y-%m-%d')
            return dt.strftime('%d/%m/%Y')
        except Exception:
            pass
        
        return str(date_str) if date_str else ''
    except Exception:
        return str(date_str) if date_str else ''


def normalize_datetime_display(value):
    """Devuelve una cadena de fecha/hora sin microsegundos.
    Si el valor es datetime, conserva hasta segundos.
    Si el valor es una cadena con microsegundos, los elimina.
    """
    if value is None:
        return ''
    try:
        from datetime import datetime
        if isinstance(value, datetime):
            if value.time() == datetime.min.time():
                return value.strftime('%Y-%m-%d')
            return value.replace(microsecond=0).strftime('%Y-%m-%d %H:%M:%S')
        value_str = str(value).strip()
        if not value_str:
            return ''
        if 'T' in value_str and value_str.count(':') >= 1:
            # Convertir ISO datetime con T en espacio para mostrarlo legible.
            value_str = value_str.replace('T', ' ', 1)
        if '.' in value_str and value_str.count(':') >= 1:
            # Eliminar microsegundos de formatos tipo YYYY-MM-DD HH:MM:SS.ffffff
            base, _ = value_str.split('.', 1)
            return base
        return value_str
    except Exception:
        return str(value)

def convert_date_to_db_format(date_str):
    """Convierte DD/MM/YYYY o DD/MM/YYYY HH:MM a objeto datetime para BD
    IMPORTANTE: Interpreta siempre como DD/MM/YYYY (formato español/latinoamericano)
    Devuelve objeto datetime para que pyodbc lo maneje correctamente
    """
    if not date_str or not isinstance(date_str, str):
        return None
    try:
        from datetime import datetime
        date_str = date_str.strip()
        # Normalizar formatos ISO con T y microsegundos
        if date_str.endswith('Z'):
            date_str = date_str[:-1]
        if 'T' in date_str and ' ' not in date_str:
            date_str = date_str.replace('T', ' ', 1)
        if '.' in date_str and date_str.count(':') >= 1:
            date_str = date_str.split('.', 1)[0]
        
        # Si ya es un objeto datetime, devolverlo
        if isinstance(date_str, datetime):
            return date_str
        
        # Si ya está en formato YYYY-MM-DD, convertir a datetime
        if date_str.startswith('20') or date_str.startswith('19') or date_str.startswith('18'):
            # Si tiene HH:MM o HH:MM:SS
            if ' ' in date_str and ':' in date_str:
                try:
                    return datetime.strptime(date_str, '%Y-%m-%d %H:%M:%S')
                except Exception:
                    try:
                        return datetime.strptime(date_str, '%Y-%m-%d %H:%M')
                    except Exception:
                        pass
            else:
                try:
                    return datetime.strptime(date_str, '%Y-%m-%d')
                except Exception:
                    pass
        
        # FORMATO PRINCIPAL CON SLASH: DD/MM/YYYY HH:MM:SS o DD/MM/YYYY HH:MM (lo que ingresa el usuario)
        if '/' in date_str and ':' in date_str and ' ' in date_str:
            try:
                return datetime.strptime(date_str, '%d/%m/%Y %H:%M:%S')
            except Exception:
                try:
                    return datetime.strptime(date_str, '%d/%m/%Y %H:%M')
                except Exception:
                    pass
        
        # FORMATO CON SLASH: DD/MM/YYYY
        if '/' in date_str:
            try:
                return datetime.strptime(date_str, '%d/%m/%Y')
            except Exception:
                pass
        
        # FORMATO CON GUIONES: DD-MM-YYYY HH:MM:SS o DD-MM-YYYY HH:MM
        if '-' in date_str and ':' in date_str and ' ' in date_str:
            try:
                return datetime.strptime(date_str, '%d-%m-%Y %H:%M:%S')
            except Exception:
                try:
                    return datetime.strptime(date_str, '%d-%m-%Y %H:%M')
                except Exception:
                    pass
        
        # FORMATO CON GUIONES: DD-MM-YYYY
        if '-' in date_str:
            try:
                return datetime.strptime(date_str, '%d-%m-%Y')
            except Exception:
                pass
        
        return None
    except Exception:
        return None


def _on_mousewheel(event, canvas):
    """Maneja el evento de rueda del mouse en un Canvas."""
    try:
        if hasattr(event, 'delta'):
            delta = -1 * (event.delta // 120)
        elif hasattr(event, 'num'):
            delta = -1 if event.num == 5 else 1
        else:
            return
        canvas.yview_scroll(delta, "units")
    except Exception:
        pass

def _on_mousewheel_block_combobox(event, canvas):
    """Desplaza el canvas pero evita que Combobox cambie valor por la rueda."""
    _on_mousewheel(event, canvas)
    return "break"

def bind_mousewheel_to_canvas(widget, canvas):
    """Vincula eventos de rueda del mouse a un Canvas."""
    try:
        canvas.bind("<MouseWheel>", lambda event: _on_mousewheel(event, canvas))
        canvas.bind("<Button-4>", lambda event: _on_mousewheel(event, canvas))
        canvas.bind("<Button-5>", lambda event: _on_mousewheel(event, canvas))
        def bind_children(w):
            try:
                if w.winfo_class() == "TCombobox":
                    w.bind("<MouseWheel>", lambda event: _on_mousewheel_block_combobox(event, canvas), add="+")
                    w.bind("<Button-4>", lambda event: _on_mousewheel_block_combobox(event, canvas), add="+")
                    w.bind("<Button-5>", lambda event: _on_mousewheel_block_combobox(event, canvas), add="+")
                else:
                    w.bind("<MouseWheel>", lambda event: _on_mousewheel(event, canvas), add="+")
                    w.bind("<Button-4>", lambda event: _on_mousewheel(event, canvas), add="+")
                    w.bind("<Button-5>", lambda event: _on_mousewheel(event, canvas), add="+")
            except Exception:
                pass
            for child in w.winfo_children():
                bind_children(child)
        bind_children(widget)
    except Exception:
        pass
def _on_treeview_mousewheel(event, treeview):
    """Maneja el evento de rueda del mouse en un Treeview."""
    try:
        if hasattr(event, 'delta'):
            treeview.yview_scroll(-1 * (event.delta // 120), "units")
        elif hasattr(event, 'num'):
            treeview.yview_scroll(-1 if event.num == 5 else 1, "units")
    except Exception:
        pass
def bind_mousewheel_to_treeview(treeview):
    """Vincula eventos de rueda del mouse a un Treeview."""
    try:
        treeview.bind("<MouseWheel>", lambda event: _on_treeview_mousewheel(event, treeview))
        treeview.bind("<Button-4>", lambda event: _on_treeview_mousewheel(event, treeview))
        treeview.bind("<Button-5>", lambda event: _on_treeview_mousewheel(event, treeview))
    except Exception:
        pass
def make_treeview_sortable(treeview):
    """
    Hace un Treeview ordenable por clicks en los encabezados.
    Los datos se ordenan de forma ascendente/descendente alternando.
    Muestra flechas (↓/↑) indicando el orden actual.
    """
    original_headings = {}
    for col in treeview['columns']:
        original_headings[col] = treeview.heading(col)['text']
    sort_state = {'column': None, 'reverse': False}
    def update_heading_arrows():
        """Actualiza los encabezados para mostrar flechas de ordenamiento."""
        for col in treeview['columns']:
            original_text = original_headings[col]
            if original_text.endswith(' 🔺') or original_text.endswith(' 🔻'):
                original_text = original_text[:-2].strip()
                original_headings[col] = original_text
            if sort_state['column'] == col:
                arrow = ' 🔺' if sort_state['reverse'] else ' 🔻'
                treeview.heading(col, text=original_text + arrow)
            else:
                treeview.heading(col, text=original_text)
    def sort_column(col_index):
        """Ordena el Treeview por la columna seleccionada."""
        items = [(treeview.set(k, col_index), k) for k in treeview.get_children('')]
        if sort_state['column'] == col_index:
            sort_state['reverse'] = not sort_state['reverse']
        else:
            sort_state['column'] = col_index
            sort_state['reverse'] = False
        try:
            items.sort(key=lambda x: float(x[0]), reverse=sort_state['reverse'])
        except (ValueError, TypeError):
            items.sort(key=lambda x: str(x[0]).lower(), reverse=sort_state['reverse'])
        for index, (val, k) in enumerate(items):
            treeview.move(k, '', index)
        update_heading_arrows()
    try:
        for col in treeview['columns']:
            treeview.heading(col, command=lambda c=col: sort_column(c))
    except Exception as e:
        print(f"Error al hacer Treeview ordenable: {e}")
def center_window(win, width=None, height=None, parent=None):
    """Centra un Toplevel en pantalla o respecto a su ventana padre.
    - Si se pasan `width`/`height`, se aplican antes de centrar.
    - Si `parent` se proporciona, se centra respecto a él; si no, se centra en la pantalla.
    """
    try:
        win.update_idletasks()
        if width and height:
            win.geometry(f"{width}x{height}")
            win.update_idletasks()
        if parent and parent.winfo_exists():
            px = parent.winfo_rootx()
            py = parent.winfo_rooty()
            pw = parent.winfo_width()
            ph = parent.winfo_height()
            ww = win.winfo_width()
            wh = win.winfo_height()
            x = px + (pw - ww) // 2
            y = py + (ph - wh) // 2
        else:
            sw = win.winfo_screenwidth()
            sh = win.winfo_screenheight()
            ww = win.winfo_width()
            wh = win.winfo_height()
            x = (sw - ww) // 2
            y = (sh - wh) // 2
        x = max(0, x)
        y = max(0, y)
        win.geometry(f"+{x}+{y}")
    except Exception:
        try:
            win.geometry("+100+100")
        except Exception:
            pass
def apply_combobox_bindings(combo_widget, stringvar):
    """Retorna un handler que aplica inmediatamente el valor seleccionado del Combobox.
    Uso:
        handler = apply_combobox_bindings(combo, var)
        combo.bind('<<ComboboxSelected>>', handler)
        combo.bind('<FocusOut>', handler)
    """
    def _handler(event=None):
        try:
            val = combo_widget.get()
            stringvar.set(val)
            try:
                combo_widget.set(val)
                combo_widget.update_idletasks()
            except Exception:
                pass
        except Exception:
            pass
        try:
            top = combo_widget.winfo_toplevel()
            try:
                top.update_idletasks()
                top.update()
            except Exception:
                try:
                    top.update_idletasks()
                except Exception:
                    pass
        except Exception:
            pass
    return _handler
class ComboboxFallaWidget(tk.Frame):
    """Widget Combobox con búsqueda para seleccionar fallas."""
    def __init__(self, parent, font=None, **kwargs):
        super().__init__(parent, **kwargs)
        self.falla_dict = {}
        self.falla_inverso = {}
        self.selected_ids = []
        self.selected_names = []
        self.ui_font = font or ("Segoe UI", 9)
        inner = tk.Frame(self)
        inner.pack(fill="both", expand=True)
        tk.Label(inner, text="Buscar:", anchor="w", font=self.ui_font).pack(side="left", padx=(0, 5))
        self.combo_var = tk.StringVar()
        self.combo = ttk.Combobox(inner, textvariable=self.combo_var, width=30, state="readonly", font=self.ui_font)
        self.combo.pack(side="left", fill="both", expand=True)
        self.combo.bind('<<ComboboxSelected>>', self.on_select)
        self.combo.bind('<KeyRelease>', self.on_key_release)
    def set_fallas(self, falla_dict):
        """Actualizar lista de fallas. falla_dict es {id_falla: nombre_falla}"""
        import re
        cleaned = {}
        for fid, name in falla_dict.items():
            raw = str(name or "").strip()
            clean_name = re.sub(r"\s*\(\d+\)\s*$", "", raw).strip()
            cleaned[fid] = clean_name
        self.falla_dict = cleaned
        self.falla_inverso = {v: k for k, v in cleaned.items()}
        nombres_sorted = sorted(cleaned.values())
        self.combo['values'] = nombres_sorted
        if self.selected_ids:
            valid_ids = [fid for fid in self.selected_ids if fid in self.falla_dict]
            self.selected_ids = valid_ids
            self.selected_names = [self.falla_dict[fid] for fid in valid_ids]
            self.combo_var.set(", ".join(self.selected_names))
    def on_select(self, event=None):
        """Manejar selección en el combobox."""
        nombre_raw = self.combo_var.get()
        nombre_seleccionado = nombre_raw.split(",")[-1].strip() if nombre_raw else ""
        if nombre_seleccionado in self.falla_inverso:
            fid = self.falla_inverso[nombre_seleccionado]
            if fid not in self.selected_ids:
                self.selected_ids.append(fid)
                self.selected_names.append(nombre_seleccionado)
            self.combo_var.set(", ".join(self.selected_names))
    def on_key_release(self, event=None):
        """Filtrar opciones mientras se escribe."""
        valor_raw = self.combo_var.get()
        valor = valor_raw.split(",")[-1].strip().lower() if valor_raw else ""
        if valor:
            opciones_filtradas = [
                nombre for nombre in self.falla_inverso.keys()
                if valor in nombre.lower() and nombre not in self.selected_names
            ]
            self.combo['values'] = sorted(opciones_filtradas)
        else:
            self.combo['values'] = sorted(self.falla_inverso.keys())
    def get_selected_id(self):
        """Retorna el ID de la falla seleccionada."""
        return self.selected_ids[0] if self.selected_ids else None
    def get_selected_ids(self):
        """Retorna los IDs de fallas seleccionadas."""
        return list(self.selected_ids)
    def get_selected_name(self):
        """Retorna el nombre de la falla seleccionada."""
        return self.combo_var.get()
    def clear_selection(self):
        """Limpiar selección."""
        self.combo_var.set("")
        self.selected_ids = []
        self.selected_names = []
    def config(self, **kwargs):
        """Override config para permitir deshabilitar el widget."""
        if 'state' in kwargs:
            self.combo.config(state=kwargs.pop('state'))
class MultiSelectFallaWidget(tk.Frame):
    """Widget con búsqueda/autocomplete para agregar fallas - todo en un recuadro."""
    def __init__(self, parent, **kwargs):
        super().__init__(parent, **kwargs, relief="solid", bd=1, bg="white")
        self.selected_falla_ids = []
        self.selected_falla_names = {}
        self.falla_dict = {}
        self.load_fallas_callback = None
        self.search_var = tk.StringVar()
        self.all_falla_ids_sorted = []
        self.falla_listbox = tk.Listbox(self, bg="#ffffff", fg="#000000", 
                                        font=("Segoe UI", 9), height=0, 
                                        relief="flat", bd=0, 
                                        state="disabled")
        self.falla_listbox.pack(fill="x", padx=4, pady=(0, 0))
        self.search_entry = ttk.Entry(self, textvariable=self.search_var, width=80)
        self.search_entry.pack(fill="x", padx=4, pady=4)
        self.search_entry.bind('<KeyRelease>', self.on_search_change)
        self.search_entry.bind('<Return>', self.on_entry_return)
        self.suggest_listbox = tk.Listbox(self, font=("Segoe UI", 9),
                                         height=0,
                                         relief="flat", bd=0, bg="white")
        self.suggest_listbox.pack(fill="both", expand=False, padx=4, pady=(0, 4))
        self.suggest_listbox.bind('<Button-1>', self.on_suggestion_click)
    def set_load_callback(self, callback):
        """Asignar función callback para cargar fallas dinámicamente."""
        self.load_fallas_callback = callback
    def set_fallas(self, falla_dict):
        """Actualizar la lista de fallas disponibles (id->nombre)."""
        self.falla_dict = falla_dict.copy()
        self.selected_falla_ids = [fid for fid in self.selected_falla_ids if fid in falla_dict]
        self.selected_falla_names = {fid: falla_dict[fid] for fid in self.selected_falla_ids}
        self.all_falla_ids_sorted = sorted(falla_dict.keys(), key=lambda fid: falla_dict[fid])
        self.update_selected_listbox()
        self.on_search_change()
    def on_search_change(self, event=None):
        """Filtrar sugerencias conforme el usuario escribe."""
        search_text = self.search_var.get().lower().strip()
        self.suggest_listbox.delete(0, tk.END)
        if search_text:
            for fid in self.all_falla_ids_sorted:
                if fid not in self.selected_falla_ids:
                    fname = self.falla_dict[fid]
                    if search_text in fname.lower():
                            self.suggest_listbox.insert(tk.END, fname)
                num_results = self.suggest_listbox.size()
                if num_results > 0:
                    max_height = min(num_results, 2)
                    self.suggest_listbox.config(height=max_height)
                else:
                    self.suggest_listbox.config(height=0)
        else:
            self.suggest_listbox.config(height=0)
    def on_suggestion_click(self, event=None):
        """Manejar clic en una falla sugerida."""
        sel = self.suggest_listbox.curselection()
        if sel:
            idx = sel[0]
            fname = self.suggest_listbox.get(idx)
            for fid in self.all_falla_ids_sorted:
                if self.falla_dict[fid] == fname and fid not in self.selected_falla_ids:
                    self.selected_falla_ids.append(fid)
                    self.selected_falla_names[fid] = fname
                    break
            self.search_var.set("")
            self.update_selected_listbox()
            self.on_search_change()
            self.search_entry.focus()
    def on_entry_return(self, event=None):
        """Manejar Enter en el entry (seleccionar primera sugerencia)."""
        if self.suggest_listbox.size() > 0:
            self.suggest_listbox.selection_set(0)
            self.on_suggestion_click()
    def update_selected_listbox(self):
        """Actualizar el contenido de la listbox de seleccionados."""
        self.falla_listbox.config(state="normal")
        self.falla_listbox.delete(0, tk.END)
        for fid in self.selected_falla_ids:
            fname = self.selected_falla_names.get(fid, "")
            self.falla_listbox.insert(tk.END, fname)
        num_selected = len(self.selected_falla_ids)
        if num_selected > 0:
            self.falla_listbox.config(height=min(num_selected, 1))
            self.falla_listbox.pack(fill="x", padx=4, pady=(4, 2))
        else:
            self.falla_listbox.config(height=0)
            self.falla_listbox.pack(fill="x", padx=4, pady=(0, 0))
        self.falla_listbox.config(state="disabled")
    def clear_selection(self):
        """Limpiar todas las selecciones."""
        self.selected_falla_ids.clear()
        self.selected_falla_names.clear()
        self.search_var.set("")
        self.update_selected_listbox()
        self.on_search_change()
    def config(self, **kwargs):
        """Override config para permitir deshabilitar el widget completo."""
        if 'state' in kwargs:
            state = kwargs.pop('state')
            if state == 'disabled':
                self.search_entry.config(state='disabled')
                self.suggest_listbox.config(state='disabled')
            else:
                self.search_entry.config(state='normal')
                self.suggest_listbox.config(state='normal')
        return super().config(**kwargs)
    def curselection(self):
        """Método compatibilidad con Listbox: retorna índices de items seleccionados."""
        falla_ids_list = self.all_falla_ids_sorted
        indices = []
        for fid in self.selected_falla_ids:
            if fid in falla_ids_list:
                indices.append(falla_ids_list.index(fid))
        return tuple(indices)
    def get(self, start, end):
        """Método compatibilidad con Listbox: retorna nombres de fallas."""
        if start == 0 and end == tk.END:
            return tuple(fname for fid, fname in sorted(self.falla_dict.items(), key=lambda x: x[1]))
        return tuple() 
    def delete(self, start, end):
        """Método compatibilidad con Listbox: limpiar fallas."""
        self.falla_dict.clear()
        self.selected_falla_ids.clear()
        self.selected_falla_names.clear()
        self.update_selected_listbox()
    def insert(self, index, item):
        """Método compatibilidad con Listbox: no usado en este contexto."""
        pass
    def bind(self, event, callback):
        """Ligar eventos al entry."""
        if event == '<Button-1>':
            self.search_entry.bind('<Button-1>', callback)
def normalize_search_text(text):
    """Normaliza texto para búsquedas de usuarios y contactos."""
    if text is None:
        return ""
    text = str(text).strip().lower()
    text = unicodedata.normalize("NFKD", text).encode("ascii", "ignore").decode("ascii")
    return " ".join(text.split())

