                cur = conn.cursor()
                cur.execute("SELECT ID_ORDEN, COALESCE(DESCRIPCION,''), COALESCE(ESTADO,'') FROM ORDENES WHERE ID_ORDEN=%s", (orden_id,))
                r = cur.fetchone()
