    def init_db(self):
        """
        Inicializa la conexión con la BD ServiceOrders.
        Lee departamentos de las bases de datos disponibles en el servidor.
        Las demás tablas ya existen y no se modifican.
        """
        cfg = {"host": DB_SERVER, "user": DB_USER, "password": DB_PASSWORD, "database": DB_NAME}
        try:
            conn = mysql.connect(**cfg)
            cur = conn.cursor()
            try:
                cur.execute("SELECT COUNT(*) FROM DEPARTAMENTOS")
                cnt_deps = cur.fetchone()[0]
            except Exception:
                cnt_deps = 0
            if not cnt_deps:
                deps = self._extract_departments_from_databases()
                for dep_name in sorted(set(deps)):
                    try:
                        cur.execute("IF NOT EXISTS (SELECT 1 FROM DEPARTAMENTOS WHERE NOMBRE_ROL = ?) INSERT INTO DEPARTAMENTOS (NOMBRE_ROL) VALUES (?)", (dep_name, dep_name))
                    except Exception:
                        pass
                conn.commit()
            cur.close()
            conn.close()
        except Exception as e:
            print(f"Error inicializando BD: {e}")
    def _extract_departments_from_databases(self):
        """
        Extrae departamentos de todas las bases de datos disponibles en el servidor.
        Busca la tabla DEPARTAMENTOS en cada BD y recolecta los nombres únicos.
        """
        import pyodbc
        departments = set()
        db_driver = '{ODBC Driver 17 for SQL Server}'
        try:
            conn_str = f'DRIVER={db_driver};SERVER={DB_SERVER};UID={DB_USER};PWD={DB_PASSWORD}'
            server_conn = pyodbc.connect(conn_str)
            server_cursor = server_conn.cursor()
            server_cursor.execute("SELECT name FROM sys.databases WHERE database_id > 4 ORDER BY name")
            all_databases = [row[0] for row in server_cursor.fetchall()]
            print(f"[init_db] Explorando {len(all_databases)} bases de datos para extraer departamentos...")
            for db_name in all_databases:
                try:
                    db_conn_str = f'DRIVER={db_driver};SERVER={DB_SERVER};DATABASE={db_name};UID={DB_USER};PWD={DB_PASSWORD}'
                    db_conn = pyodbc.connect(db_conn_str)
                    db_cursor = db_conn.cursor()
                    db_cursor.execute("""
                        SELECT TABLE_NAME FROM INFORMATION_SCHEMA.TABLES 
                        WHERE TABLE_NAME = 'DEPARTAMENTOS' AND TABLE_TYPE = 'BASE TABLE'
                    """)
                    if db_cursor.fetchone():
                        db_cursor.execute("""
                            SELECT COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS 
                            WHERE TABLE_NAME = 'DEPARTAMENTOS' 
                            ORDER BY ORDINAL_POSITION
                        """)
                        columnas = [row[0] for row in db_cursor.fetchall()]
                        col_nombre = None
                        for col in ['NOMBRE_ROL', 'NOMBRE', 'DESCRIPCION', 'NOMBRE_DEPARTAMENTO']:
                            if col in columnas:
                                col_nombre = col
                                break
                        if col_nombre:
                            db_cursor.execute(f"SELECT DISTINCT [{col_nombre}] FROM DEPARTAMENTOS WHERE [{col_nombre}] IS NOT NULL AND [{col_nombre}] != ''")
                            for row in db_cursor.fetchall():
                                if row[0]:
                                    departments.add(row[0])
                            print(f"[init_db]   ✓ {db_name}: {len([d for d in departments])} dpts")
                    db_conn.close()
                except Exception as e:
                    pass
            server_conn.close()
        except Exception as e:
            print(f"[init_db] Error extrayendo departamentos: {e}")
        if not departments:
            print("[init_db] No se encontraron departamentos en BDs, usando lista por defecto...")
            departments = {
                'Programación de Producción/Planeación', 'Urdido', 'Tricot', 'Circular',
                'Tintorería', 'Ramas', 'Máquinas Especiales/Afelpado', 'Estampado',
                'Almacén de Cajas', 'Almacén de Crudos', 'Almacén de Productos Químicos',
                'Almacén de Julios', 'Almacén de Refacciones', 'Almacén de Producto Terminado',
                'Laboratorio Químico', 'Laboratorio Físico', 'Ecología/Medio Ambiente',
                'Sistemas', 'Bondeado / Laminado', 'Mantenimiento Eléctrico', 'Mantenimiento General',
                'Mantenimiento Mecánico', 'Control de Calidad', 'Sistema Gestión de Calidad',
                'Logística y Suministro', 'Recursos Humanos / Gestión de Talento',
                'Créditos y Cobranzas', 'Ventas CID', 'Diseño', 'Servicio Médico',
                'Seguridad e Higiene', 'Salud Ocupacional', 'Servicio al Cliente',
                'Operaciones', 'Tornos', 'Compras'
            }
        return list(departments)
    def get_user_permissions(self, usuario_id=None, id_departamento=None):
        """Recupera permisos del departamento (sin validar por usuario) y reutiliza caché en memoria."""
        perms = set()
        dep_key = str(id_departamento).strip() if id_departamento else ""
        if not dep_key:
            dep_key = str(getattr(self, "current_dep_id", "") or "").strip()
        if dep_key:
            cached = self._permissions_by_department.get(dep_key)
            if cached is not None:
                return set(cached)
        else:
            return perms
        cfg = {"host": DB_SERVER, "user": DB_USER, "password": DB_PASSWORD, "database": DB_NAME}
        conn = mysql.connect(**cfg)
        cur = conn.cursor()
        cur.execute("""
            SELECT p.nombre_permiso
            FROM departamentos_permisos dp
            JOIN permisos p ON dp.id_permiso = p.id_permiso
            WHERE dp.id_departamento = %s
        """, (dep_key,))
        for r in cur.fetchall():
            perms.add(r[0])
        cur.close()
        conn.close()
        self._permissions_by_department[dep_key] = set(perms)
        return perms
    def try_login(self):
        user = self.user_var.get().strip()
        pw = self.pass_var.get()
        if not user:
            messagebox.showwarning("Acceso", "Ingrese usuario")
            return
        cfg = {"host": DB_SERVER, "user": DB_USER, "password": DB_PASSWORD, "database": DB_NAME}
        try:
            conn = mysql.connect(**cfg)
            cur = conn.cursor()
            cur.execute("SELECT ID_USUARIO, PASSWORD_HASH, NOMBRE_USUARIO, ID_DEPARTAMENTO, NIVEL, ESTADO, USUARIO_LOGIN, INTENTOS_FALLIDOS FROM USUARIOS WHERE USUARIO_LOGIN = %s", (user,))
            row = cur.fetchone()
            if not row:
                user_norm = self.normalize_login_text(user)
                if user_norm:
                    cur.execute("SELECT ID_USUARIO, PASSWORD_HASH, NOMBRE_USUARIO, ID_DEPARTAMENTO, NIVEL, ESTADO, USUARIO_LOGIN, INTENTOS_FALLIDOS FROM USUARIOS")
                    for cand in cur.fetchall():
                        if self.normalize_login_text(cand[6]) == user_norm:
                            row = cand
                            break
            cur.close()
            conn.close()
        except Exception as e:
            messagebox.showerror("Error BD", f"No se pudo conectar a la base de datos:\n{e}")
            return
        if row:
            estado_user = row[5] if len(row) > 5 else None
            if estado_user and estado_user.lower() in ("bloqueado", "suspendido", "inactivo"):
                dept_name = ""
                try:
                    conn = mysql.connect(**cfg)
                    cur = conn.cursor()
                    cur.execute("SELECT NOMBRE_ROL FROM DEPARTAMENTOS WHERE ID_DEPARTAMENTO = %s", (row[3],))
                    r = cur.fetchone()
                    cur.close()
                    conn.close()
                    dept_name = r[0] if r else ""
                except:
                    pass
                nombre_usuario = row[2] or user
                self.log_action(row[0], f"Intento de login - Usuario bloqueado/inactivo - Usuario: {nombre_usuario}", dept_name)
                log_login(row[0], user, nombre_usuario, row[3], dept_name, exitoso=False, razon="Usuario bloqueado/inactivo")
                messagebox.showerror("Acceso", "El usuario está bloqueado o inactivo. No puede acceder a la aplicación.")
                return
        password_stored = row[1] if row else None
        tiene_contraseña = password_stored and str(password_stored).strip() and str(password_stored).strip().lower() != 'null'
        password_valida = False
        if row:
            if tiene_contraseña:
                password_valida = self.is_password_valid(pw, password_stored)
            else:
                password_valida = (pw == "" or pw is None or str(pw).strip() == "")
        if row and password_valida:
            usuario_id = row[0]
            nombre = row[2] or user
            id_departamento = row[3]
            nivel = int(row[4] or 1)
            self.current_user_id = usuario_id
            self.current_dep_id = id_departamento
            self.current_nivel = nivel
            self.current_user_name = nombre
            self.current_user_login = (row[6] if len(row) > 6 and row[6] else user).strip()
            self.is_admin = nivel >= 10
            self.is_admin_login = self.current_user_login.lower().startswith('admin')
            try:
                conn = mysql.connect(**cfg)
                cur = conn.cursor()
                cur.execute("SELECT nombre_rol FROM departamentos WHERE id_departamento = %s", (id_departamento,))
                r = cur.fetchone()
                cur.execute("UPDATE USUARIOS SET INTENTOS_FALLIDOS = 0 WHERE ID_USUARIO = %s", (usuario_id,))
                conn.commit()
                cur.close()
                conn.close()
                self.current_dep_name = r[0] if r else ""
            except Exception:
                self.current_dep_name = ""
            token = str(uuid.uuid4())
            self.current_session_id = None
            self.current_session_token = token
            try:
                self.log_action(usuario_id, f"LOGIN_EXITOSO - Usuario: {nombre}", self.current_dep_name)
                log_login(usuario_id, user, nombre, id_departamento, self.current_dep_name, exitoso=True)
            except Exception:
                pass
            try:
                self.root.withdraw()
            except Exception:
                pass
            try:
                self._cached_permissions = self.get_user_permissions(usuario_id, id_departamento)
            except Exception:
                self._cached_permissions = set()
            self.open_main_window(usuario_id, nombre, id_departamento, nivel)
        else:
            if row:
                usuario_id = row[0]
                nombre_usuario = row[2] or user
                intentos_actuales = (row[7] if len(row) > 7 else 0) or 0
                intentos_nuevos = intentos_actuales + 1
                dept_id = row[3]
                dept_name = ""
                try:
                    conn = mysql.connect(**cfg)
                    cur = conn.cursor()
                    cur.execute("SELECT NOMBRE_ROL FROM DEPARTAMENTOS WHERE ID_DEPARTAMENTO = %s", (dept_id,))
                    r = cur.fetchone()
                    dept_name = r[0] if r else ""
                    if intentos_nuevos >= 3:
                        cur.execute("UPDATE USUARIOS SET INTENTOS_FALLIDOS = %s, ESTADO = %s WHERE ID_USUARIO = %s", (intentos_nuevos, "Suspendido", usuario_id))
                        conn.commit()
                        self.log_action(usuario_id, f"LOGIN_FALLIDO - Usuario bloqueado (3 intentos fallidos) - Usuario: {nombre_usuario}", dept_name)
                        log_login(usuario_id, user, nombre_usuario, dept_id, dept_name, exitoso=False, razon="Bloqueado por 3 intentos fallidos")
                        messagebox.showerror("Acceso", f"Su usuario ha sido bloqueado por 3 intentos fallidos de login.\nContacte al administrador para desbloquear su cuenta.")
                    else:
                        cur.execute("UPDATE USUARIOS SET INTENTOS_FALLIDOS = %s WHERE ID_USUARIO = %s", (intentos_nuevos, usuario_id))
                        conn.commit()
                        self.log_action(usuario_id, f"LOGIN_FALLIDO - Intento {intentos_nuevos}/3 - Usuario: {nombre_usuario}", dept_name)
                        log_login(usuario_id, user, nombre_usuario, dept_id, dept_name, exitoso=False, razon=f"Contraseña incorrecta (intento {intentos_nuevos}/3)")
                        messagebox.showerror("Acceso", f"Usuario o contraseña incorrectos.\nIntentos restantes: {3 - intentos_nuevos}")
                    cur.close()
                    conn.close()
                except Exception as e:
                    self.log_action(usuario_id, f"Error al procesar login fallido", str(e))
                    messagebox.showerror("Acceso", "Usuario o contraseña incorrectos")
            else:
                try:
                    self.log_action(None, f"LOGIN_FALLIDO - Usuario no existe: {user}", "Intento de acceso")
                    log_login(None, user, 'DESCONOCIDO', None, 'DESCONOCIDO', exitoso=False, razon="Usuario no existe")
                except Exception:
                    pass
                messagebox.showerror("Acceso", "Usuario o contraseña incorrectos")
    def log_action(self, usuario_id, accion, detalles=None):
        """Registra una acción con detalles en la tabla logs. Mantiene compatibilidad con código existente."""
        try:
            log_accion_generica(usuario_id, self.current_user_name if hasattr(self, 'current_user_name') else 'DESCONOCIDO', accion, {'detalles': detalles})
        except Exception:
            pass
        cfg = {"host": DB_SERVER, "user": DB_USER, "password": DB_PASSWORD, "database": DB_NAME}
        try:
            if not usuario_id or usuario_id == 'None':
                usuario_id = 'USR0001'
            else:
                usuario_id = str(usuario_id)
            user_exists = False
            try:
                conn = mysql.connect(**cfg)
                cur = conn.cursor()
                cur.execute("SELECT TOP 1 ID_USUARIO FROM USUARIOS WHERE ID_USUARIO = ?", (usuario_id,))
                user_exists = cur.fetchone() is not None
                cur.close()
                conn.close()
            except Exception:
                pass
            if not user_exists:
                usuario_id = 'USR0001'
            conn = mysql.connect(**cfg)
            cur = conn.cursor()
            cur.execute("SELECT ISNULL(MAX(ID_LOG), 0) FROM LOGS")
            next_id = cur.fetchone()[0] + 1
            cur.execute(
                "INSERT INTO LOGS (ID_LOG, ID_USUARIO, ACCION, DETALLES, FECHA) VALUES (?, ?, ?, ?, GETDATE())", 
                (next_id, usuario_id, accion, detalles)
            )
            conn.commit()
            cur.close()
            conn.close()
        except Exception as e:
            log_debug(f"No se pudo registrar log en BD: {e}")
    def _limpiar_bitacora(self, callback_refresh):
        """Limpia el historial de la bitécora de logins. Solo para admin."""
        if not self.is_admin:
            messagebox.showerror("Acceso Denegado", "Solo el administrador puede limpiar el historial")
            return
        if messagebox.askyesno("Confirmar", "¿Está seguro que desea eliminar TODO el historial de logins?\nEsta acción es irreversible."):
            try:
                cfg = {"host": DB_SERVER, "user": DB_USER, "password": DB_PASSWORD, "database": DB_NAME}
                conn = mysql.connect(**cfg)
                cur = conn.cursor()
                cur.execute("DELETE FROM LOGS WHERE ACCION LIKE '%LOGIN%'")
                conn.commit()
                eliminados = cur.rowcount
                cur.close()
                conn.close()
                messagebox.showinfo("Exito", f"Se eliminaron {eliminados} registros del historial")
                callback_refresh()
            except Exception as e:
                messagebox.showerror("Error", f"Error al limpiar historial:\n{str(e)[:100]}")
    def is_allowed_manage_users(self):
        """
        Retorna True si el usuario current puede gestionar usuarios.
        Solo Administracion o Sistemas (o nivel >=4) pueden.
        Usuarios con login 'admin' o que empiecen con 'admin' también pueden.
        """
        try:
            if getattr(self, "current_nivel", 0) >= 4:
                return True
            login = getattr(self, "current_user_login", "").strip().lower()
            if login.startswith("admin"):
                return True
            dep = getattr(self, "current_dep_name", "").lower()
            return dep in ("administracion", "sistemas", "mantenimiento")
        except Exception:
            return False
    def can_create_users(self):
        """
        Retorna True si el usuario current puede CREAR usuarios.
        Solo el admin puede crear usuarios.
        """
        try:
            return getattr(self, "is_admin", False)
        except Exception:
            return False
    def can_edit_orders(self):
        """
        Retorna True si el usuario current puede editar órdenes de trabajo.
        Admin, departamentos con 'mantenimiento' en el nombre, y usuarios con login admin*.
        """
        try:
            if getattr(self, "is_admin", False):
                return True
            if getattr(self, "is_admin_login", False):
                return True
            dep = (getattr(self, "current_dep_name", "") or "").lower()
            return "mantenimiento" in dep
        except Exception:
            return False
    def save_user_turno_to_db(self, usuario_id, turno_nombre):
        """Guarda el turno seleccionado para el usuario en la BD."""
        try:
            log_debug(f"save_user_turno_to_db called: usuario_id={usuario_id}, turno_nombre={turno_nombre}")
            
            if not usuario_id or not turno_nombre:
                log_debug(f"save_user_turno_to_db: usuario_id o turno_nombre está vacío")
                return False
            
            cfg = {"host": DB_SERVER, "user": DB_USER, "password": DB_PASSWORD, "database": DB_NAME}
            conn = mysql.connect(**cfg)
            cur = conn.cursor()
            
            # Obtener ID_TURNO del nombre
            log_debug(f"Buscando turno: {turno_nombre}")
            cur.execute("SELECT ID_TURNO FROM TURNOS WHERE NOMBRE_TURNO = %s", (turno_nombre,))
            row = cur.fetchone()
            if not row:
                log_debug(f"No se encontró el turno: {turno_nombre}")
                cur.close()
                conn.close()
                return False
            
            id_turno = row[0]
            log_debug(f"ID_TURNO encontrado: {id_turno}")
            
            # Actualizar el turno del usuario
            log_debug(f"Actualizando usuario {usuario_id} con turno {id_turno}")
            cur.execute("UPDATE USUARIOS SET ID_TURNO = %s WHERE ID_USUARIO = %s", (id_turno, usuario_id))
            conn.commit()
            
            log_debug(f"Turno actualizado exitosamente para usuario {usuario_id}")
            cur.close()
            conn.close()
            return True
        except Exception as e:
            log_debug(f"Error guardando turno del usuario {usuario_id}: {e}")
            import traceback
            log_debug(traceback.format_exc())
            return False

    def is_maintenance_or_systems(self):
        """Retorna True para todos los usuarios: el selector de turno está disponible para cualquier departamento."""
        return True
    def user_has_permission(self, usuario_id, permission_name):
        """
        Verifica si el usuario tiene un permiso específico.
        Los permisos están asignados a departamentos a través de DEPARTAMENTOS_PERMISOS.
        Permisos disponibles:
        - 'ver_catalogos' - Ver pestaña Catálogos
        - 'ver_ordenes' - Ver pestaña Órdenes
        - 'ver_reportes' - Ver pestaña Reportes
        - 'ver_seguridad' - Ver pestaña Seguridad
        - 'crear_orden' - Crear nuevas órdenes
        - 'editar_orden' - Editar órdenes
        - 'crear_falla' - Crear fallas en catálogo
        - 'editar_falla' - Editar fallas en catálogo
        - 'editar_usuarios' - Gestionar usuarios
        - 'ver_bitacora' - Ver bitácora de logins
        """
        try:
            if getattr(self, "is_admin", False):
                return True
            dep_id = getattr(self, "current_dep_id", None)
            if not dep_id:
                return True
            perms = self.get_user_permissions(id_departamento=dep_id)
            permiso_buscado = str(permission_name or "").strip().lower()
            return permiso_buscado in {str(p).strip().lower() for p in perms}
        except Exception as e:
            log_debug(f"Error en user_has_permission: {e}")
            return True
    def table_has_column(self, table_name, column_name):
        """Verifica si una tabla tiene una columna determinada en la base de datos."""
        try:
            if MSSQL_AVAILABLE:
                try:
                    conn = pyodbc.connect(f"DRIVER={DB_DRIVER};SERVER={DB_SERVER};DATABASE={DB_NAME};UID={DB_USER};PWD={DB_PASSWORD};")
                    cur = conn.cursor()
                    cur.execute("""
                        SELECT COUNT(*) 
                        FROM INFORMATION_SCHEMA.COLUMNS 
                        WHERE TABLE_SCHEMA = 'dbo' 
                          AND TABLE_NAME = ? 
                          AND COLUMN_NAME = ?
                    """, (table_name, column_name))
                    result = cur.fetchone()
                    exists = result[0] > 0 if result else False
                    cur.close()
                    conn.close()
                    log_debug(f"table_has_column('{table_name}', '{column_name}'): {exists}")
                    return exists
                except Exception as e:
                    log_debug(f"table_has_column SQL Server error: {e}")
                    return False
            else:
                cfg = {"host": DB_SERVER, "user": DB_USER, "password": DB_PASSWORD, "database": DB_NAME}
                conn = mysql.connect(**cfg)
                cur = conn.cursor()
                try:
                    cur.execute(
                        "SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=%s AND TABLE_NAME=%s AND COLUMN_NAME=%s",
                        (DB_NAME, table_name, column_name)
                    )
                    exists = cur.fetchone()[0] > 0
                except Exception:
                    try:
                        cur.execute(
                            "SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_CATALOG=%s AND TABLE_NAME=%s AND COLUMN_NAME=%s",
                            (DB_NAME, table_name, column_name)
                        )
                        exists = cur.fetchone()[0] > 0
                    except Exception:
                        exists = False
                cur.close(); conn.close()
                return exists
        except Exception as e:
            log_debug(f"table_has_column exception (final fallback): {e}")
            return False
    def is_auto_increment_column(self, table_name, column_name):
        """Retorna True si la columna es AUTO_INCREMENT en MySQL."""
        try:
            cfg = {"host": DB_SERVER, "user": DB_USER, "password": DB_PASSWORD, "database": DB_NAME}
            conn = mysql.connect(**cfg)
            cur = conn.cursor()
            try:
                cur.execute(
                    "SELECT EXTRA FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=%s AND TABLE_NAME=%s AND COLUMN_NAME=%s",
                    (DB_NAME, table_name, column_name)
                )
                row = cur.fetchone()
                if row and 'auto_increment' in str(row[0]).lower():
                    cur.close(); conn.close();
                    return True
            except Exception:
                pass
            try:
                cur.execute(
                    "SELECT COLUMNPROPERTY(OBJECT_ID(QUOTENAME(TABLE_SCHEMA) + '.' + QUOTENAME(TABLE_NAME)), COLUMN_NAME, 'IsIdentity') AS is_id "
                    "FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME=%s AND COLUMN_NAME=%s",
                    (table_name, column_name)
                )
                row2 = cur.fetchone()
                cur.close(); conn.close()
                if row2 and int(row2[0] or 0) == 1:
                    return True
            except Exception:
                try:
                    cur.close(); conn.close()
                except Exception:
                    pass
            return False
        except Exception:
            return False
    def get_next_numeric_id(self, table_name, id_column):
        """Obtiene siguiente ID numurico como MAX+1 para PKs no autoincrement."""
        try:
            cfg = {"host": DB_SERVER, "user": DB_USER, "password": DB_PASSWORD, "database": DB_NAME}
            conn = mysql.connect(**cfg)
            cur = conn.cursor()
            if MSSQL_AVAILABLE:
                cur.execute(f"SELECT COALESCE(MAX(TRY_CAST({id_column} AS BIGINT)),0)+1 FROM {table_name}")
            else:
                cur.execute(f"SELECT COALESCE(MAX(CAST({id_column} AS UNSIGNED)),0)+1 FROM {table_name}")
            nxt = cur.fetchone()[0]
            cur.close(); conn.close()
            return int(nxt or 1)
        except Exception:
            return 1
    def normalize_login_text(self, login_text):
        """Normaliza login para comparación tolerante a acentos y separadores."""
        try:
            txt = str(login_text or "").strip().lower()
            txt = unicodedata.normalize("NFKD", txt)
            txt = "".join(ch for ch in txt if not unicodedata.combining(ch))
            for sep in (" ", "_", "-", "."):
                txt = txt.replace(sep, "")
            return txt
        except Exception:
            return str(login_text or "").strip().lower()
    def is_password_valid(self, input_password, stored_password):
        """Valida contraseña soportando texto plano y SHA-256."""
        try:
            entered = str(input_password or "")
            saved = str(stored_password or "")
            if entered == saved:
                return True
            entered_sha256 = hashlib.sha256(entered.encode("utf-8")).hexdigest()
            return entered_sha256.lower() == saved.lower()
        except Exception:
            return False
    def get_ordenes_fecha_column(self):
        """Retorna la columna de fecha disponible para ORDENES."""
        try:
            if self.table_has_column('ORDENES', 'FECHA_SOLICITUD'):
                return 'FECHA_SOLICITUD'
            if self.table_has_column('ORDENES', 'FECHA_CREACION'):
                return 'FECHA_CREACION'
            return None
        except Exception:
            return None
    def get_order_permissions(self, order_id):
        """
        Retorna diccionario con información de permisos para una orden:
        {
            'solicita_id': ID_USUARIO que creó la orden,
            'id_tecnico': ID_USUARIO asignado (personal asignado), o None,
            'estado': Estado actual 'N', 'P', 'C', 'X', 'F',
            'is_current_user_solicitante': True si el usuario actual es el solicitante,
            'is_current_user_tecnico': True si el usuario actual es el personal asignado,
            'is_current_user_supervisor': True si el usuario es Supervisor/Gestor,
        }
        """
        try:
            cfg = {"host": DB_SERVER, "user": DB_USER, "password": DB_PASSWORD, "database": DB_NAME}
            conn = mysql.connect(**cfg)
            cur = conn.cursor()
            solicita_col = 'SOLICITA'
            if not self.table_has_column('ORDENES', 'SOLICITA'):
                if self.table_has_column('ORDENES', 'ID_USUARIO'):
                    solicita_col = 'ID_USUARIO'
                elif self.table_has_column('ORDENES', 'SOLICITANTE'):
                    solicita_col = 'SOLICITANTE'
            estado_col = 'ESTADO'
            if not self.table_has_column('ORDENES', 'ESTADO'):
                if self.table_has_column('ORDENES', 'estado'):
                    estado_col = 'estado'
            sql = f"SELECT {solicita_col}, {estado_col} FROM ORDENES WHERE ID_ORDEN = ?"
            try:
                cur.execute(sql, (order_id,))
                result = cur.fetchone()
            except Exception:
                result = None
                try:
                    cur.execute("SELECT ID_USUARIO, ESTADO FROM ORDENES WHERE ID_ORDEN = ?", (order_id,))
                    result = cur.fetchone()
                except Exception:
                    try:
                        cur.execute("SELECT SOLICITANTE, ESTADO FROM ORDENES WHERE ID_ORDEN = ?", (order_id,))
                        result = cur.fetchone()
                    except Exception:
                        result = None
            solicita_id = result[0] if result else None
            estado = (result[1] or 'N').upper() if result else 'N'
            id_tecnico = None
            if self.table_has_column('ORDENES', 'ID_TECNICO'):
                try:
                    cur.execute("SELECT ID_TECNICO FROM ORDENES WHERE ID_ORDEN = ?", (order_id,))
                    r = cur.fetchone()
                except Exception:
                    r = None
                id_tecnico = r[0] if r and r[0] else None
            cur.close(); conn.close()
            current_user = getattr(self, 'current_user_id', None)
            is_supervisor = self.is_maintenance_or_systems()
            return {
                'solicita_id': solicita_id,
                'id_tecnico': id_tecnico,
                'estado': estado,
                'is_current_user_solicitante': current_user == solicita_id,
                'is_current_user_tecnico': current_user == id_tecnico if id_tecnico else False,
                'is_current_user_supervisor': is_supervisor,
            }
        except Exception as e:
            print(f"Error en get_order_permissions: {e}")
            return {
                'solicita_id': None, 'id_tecnico': None, 'estado': 'N',
                'is_current_user_solicitante': False, 'is_current_user_tecnico': False,
                'is_current_user_supervisor': False,
            }
    def can_modify_order(self, order_id, field_or_section=None):
        """
        Determina si el usuario actual puede modificar una orden.
        field_or_section puede ser: 'info_general', 'descripcion_falla', 'fallas', 'solucion', None (para modificar la orden en general)
        Reglas:
        - Estado 'C' (Cerrado): NADIE puede modificar
        - Estado 'X' (Cancelado): NADIE puede modificar
        - Solicitante en estado 'P+': solo puede ver, no modificar
        - Personal asignado (técnico): puede modificar en N, P, F (con restricciones en F)
        - Supervisor: puede modificar casi todo excepto 'info_general' y 'descripcion_falla'
        """
        if getattr(self, 'is_admin', False):
            return True
        perms = self.get_order_permissions(order_id)
        estado = perms.get('estado', 'N')
        if estado in ('C', 'X'):
            return False
        if perms['is_current_user_solicitante']:
            if estado == 'N':
                if field_or_section in ('fallas', 'descripcion_falla', None):
                    return True
            return False
        if perms['is_current_user_tecnico']:
            if estado in ('N', 'P', 'F'):
                if estado == 'F':
                    if field_or_section in ('fecha_terminado', 'tiempo_muerto', None):
                        return True
                else:
                    if field_or_section not in ('info_general',):
                        return True
            return False
        if perms['is_current_user_supervisor']:
            if field_or_section not in ('info_general', 'descripcion_falla'):
                return True
            if field_or_section is None:
                return True
        return False
    def get_borrador_orden(self, order_id, user_id):
        """Obtiene el borrador guardado de una orden para el usuario actual"""
        try:
            if not self.table_has_column('borradores_ordenes', 'id_orden'):
                return None
            cfg = {"host": DB_SERVER, "user": DB_USER, "password": DB_PASSWORD, "database": DB_NAME}
            conn = mysql.connect(**cfg)
            cur = conn.cursor()
            cur.execute("SELECT datos_cambios, fecha_guardado FROM borradores_ordenes WHERE id_orden = ? AND id_usuario = ?", (order_id, user_id))
            resultado = cur.fetchone()
            cur.close()
            conn.close()
            if resultado:
                import json
                datos = json.loads(resultado[0]) if resultado[0] else {}
                fecha = resultado[1]
                return {'datos': datos, 'fecha': fecha}
            return None
        except Exception as e:
            print(f"Error al obtener borrador: {e}")
            return None
    def guardar_borrador_orden(self, order_id, user_id, cambios):
        """Guarda los cambios de una orden como borrador"""
        try:
            import json
            if not self.table_has_column('borradores_ordenes', 'id_orden'):
                print("Advertencia: tabla 'borradores_ordenes' no encontrada. No se guarda borrador.")
                return False
            cfg = {"host": DB_SERVER, "user": DB_USER, "password": DB_PASSWORD, "database": DB_NAME}
            conn = mysql.connect(**cfg)
            cur = conn.cursor()
            if isinstance(cambios, str):
                datos_json = cambios
            else:
                datos_json = json.dumps(cambios)
            try:
                cur.execute("UPDATE borradores_ordenes SET datos_cambios = ?, fecha_guardado = CURRENT_TIMESTAMP WHERE id_orden = ? AND id_usuario = ?", (datos_json, order_id, user_id))
                if getattr(cur, 'rowcount', None) in (None, 0):
                    cur.execute("INSERT INTO borradores_ordenes (id_orden, id_usuario, datos_cambios, fecha_guardado) VALUES (?, ?, ?, CURRENT_TIMESTAMP)", (order_id, user_id, datos_json))
                conn.commit()
            finally:
                try:
                    cur.close()
                except Exception:
                    pass
                try:
                    conn.close()
                except Exception:
                    pass
            return True
        except Exception as e:
            print(f"Error al guardar borrador: {e}")
            return False
    def eliminar_borrador_orden(self, order_id, user_id):
        """Elimina el borrador de una orden"""
        try:
            cfg = {"host": DB_SERVER, "user": DB_USER, "password": DB_PASSWORD, "database": DB_NAME}
            conn = mysql.connect(**cfg)
            cur = conn.cursor()
            cur.execute("""DELETE FROM borradores_ordenes 
                          WHERE id_orden = %s AND id_usuario = %s""", (order_id, user_id))
            conn.commit()
            cur.close()
            conn.close()
            return True
        except Exception as e:
            print(f"Error al eliminar borrador: {e}")
            return False
    def get_visible_departments(self, id_departamento, nivel):
        """
        Retorna lista de (id_departamento, nombre_rol) que el usuario puede ver.
        Regla solicitada:
         - Si el usuario pertenece a 'Administracion', 'Sistemas' o 'Mantenimiento'
           (o su nivel >= 4) -> ve todos los departamentos.
         - En caso contrario -> sélo su propio departamento.
        """
        cfg = {"host": DB_SERVER, "user": DB_USER, "password": DB_PASSWORD, "database": DB_NAME}
        try:
            conn = mysql.connect(**cfg)
            cur = conn.cursor()
            cur.execute("SELECT ID_DEPARTAMENTO, NOMBRE_ROL FROM DEPARTAMENTOS ORDER BY ID_DEPARTAMENTO")
            all_deps = cur.fetchall()
            cur.execute("SELECT nombre_rol FROM departamentos WHERE id_departamento = %s", (id_departamento,))
            row = cur.fetchone()
            cur.close()
            conn.close()
            dep_name = row[0] if row else None
        except Exception:
            if id_departamento:
                return [(id_departamento, dep_name or "Desconocido")]
            return []
        if dep_name and (dep_name.lower() in ("administracion", "sistemas", "mantenimiento") or (nivel is not None and int(nivel) >= 4)):
            return all_deps
        for d in all_deps:
            if d[0] == id_departamento:
                return [d]
        return []
    def get_departments_with_visibility(self, id_departamento, nivel):
        """
        Retorna lista de (id_departamento, nombre_rol, visible_bool).
        Reglas:
         - Si el usuario pertenece a 'Administracion', 'Sistemas' o 'Mantenimiento'
           (o nivel >= 4) -> visible=True para todos.
         - En caso contrario -> visible=True solo para su propio departamento.
        """
        cfg = {"host": DB_SERVER, "user": DB_USER, "password": DB_PASSWORD, "database": DB_NAME}
        try:
            conn = mysql.connect(**cfg)
            cur = conn.cursor()
            cur.execute("SELECT ID_DEPARTAMENTO, NOMBRE_ROL FROM DEPARTAMENTOS ORDER BY ID_DEPARTAMENTO")
            all_deps = cur.fetchall()
            cur.execute("SELECT nombre_rol FROM departamentos WHERE id_departamento = %s", (id_departamento,))
            row = cur.fetchone()
            cur.close()
            conn.close()
            user_dep_name = row[0] if row else None
        except Exception:
            return []
        is_global_viewer = False
        if user_dep_name:
            is_global_viewer = (user_dep_name.lower() in ("administracion", "sistemas", "mantenimiento")) or (nivel is not None and int(nivel) >= 4)
        res = []
        for did, dname in all_deps:
            if is_global_viewer:
                res.append((did, dname, True))
            else: 
                res.append((did, dname, did == id_departamento))
        return res

