    def ensure_chat_tables(self):
        """Crea la tabla de mensajes de chat si no existe."""
        try:
            conn_str = f"DRIVER={DB_DRIVER};SERVER={DB_SERVER};DATABASE={DB_NAME};UID={DB_USER};PWD={DB_PASSWORD};"
            conn = pyodbc.connect(conn_str)
            cur = conn.cursor()
            create_table_sql = """
            IF NOT EXISTS (SELECT * FROM sysobjects WHERE name='CHAT_MENSAJES' AND xtype='U')
            BEGIN
                CREATE TABLE CHAT_MENSAJES (
                    ID_MENSAJE INT IDENTITY(1,1) PRIMARY KEY,
                    ID_REMITENTE INT NOT NULL,
                    ID_DESTINATARIO INT NOT NULL,
                    MENSAJE NVARCHAR(MAX) NOT NULL,
                    FECHA_ENVIO DATETIME DEFAULT GETDATE(),
                    LEIDO TINYINT DEFAULT 0,
                    INDEX idx_usuarios (ID_REMITENTE, ID_DESTINATARIO),
                    INDEX idx_fecha (FECHA_ENVIO)
                )
            END
            """
            cur.execute(create_table_sql)
            conn.commit()
            try:
                alter_fk1 = """
                IF NOT EXISTS (SELECT * FROM INFORMATION_SCHEMA.KEY_COLUMN_USAGE WHERE CONSTRAINT_NAME='fk_remitente')
                ALTER TABLE CHAT_MENSAJES ADD CONSTRAINT fk_remitente
                FOREIGN KEY (ID_REMITENTE) REFERENCES USUARIOS(ID_USUARIO) ON DELETE CASCADE
                """
                cur.execute(alter_fk1)
                conn.commit()
            except Exception as e:
                log_debug(f"FK remitente ya existe o error: {e}")
            try:
                alter_fk2 = """
                IF NOT EXISTS (SELECT * FROM INFORMATION_SCHEMA.KEY_COLUMN_USAGE WHERE CONSTRAINT_NAME='fk_destinatario')
                ALTER TABLE CHAT_MENSAJES ADD CONSTRAINT fk_destinatario
                FOREIGN KEY (ID_DESTINATARIO) REFERENCES USUARIOS(ID_USUARIO) ON DELETE CASCADE
                """
                cur.execute(alter_fk2)
                conn.commit()
            except Exception as e:
                log_debug(f"FK destinatario ya existe o error: {e}")
            cur.close()
            conn.close()
            return True
        except Exception as e:
            log_debug(f"Error creando tabla de chat: {e}")
            return False

    def get_chat_contacts(self, search_text=""):
        """Retorna usuarios disponibles para chatear."""
        try:
            conn_str = f"DRIVER={DB_DRIVER};SERVER={DB_SERVER};DATABASE={DB_NAME};UID={DB_USER};PWD={DB_PASSWORD};"
            conn = pyodbc.connect(conn_str)
            cur = conn.cursor()
            query = """
                SELECT ID_USUARIO, NOMBRE_USUARIO, USUARIO_LOGIN
                FROM USUARIOS
                WHERE ID_USUARIO != ?
            """
            params = [str(self.current_user_id)]
            if search_text:
                query += " AND (LOWER(COALESCE(NOMBRE_USUARIO, '')) LIKE ? OR LOWER(COALESCE(USUARIO_LOGIN, '')) LIKE ?)"
                token = f"%{normalize_search_text(search_text)}%"
                params.extend([token, token])
            query += " ORDER BY COALESCE(NOMBRE_USUARIO, USUARIO_LOGIN), USUARIO_LOGIN"
            cur.execute(query, params)
            rows = cur.fetchall()
            cur.close()
            conn.close()
            result = [(int(row[0]) if row[0] else None, row[1], row[2]) for row in rows]
            log_debug(f"[CHAT CONTACTS] Recuperados {len(result)} contactos disponibles")
            return result
        except Exception as e:
            log_debug(f"Error consultando contactos de chat: {e}")
            return []

    def get_chat_messages(self, contact_id):
        """Carga los mensajes entre el usuario actual y un contacto desde la BD."""
        if not contact_id or not getattr(self, 'current_user_id', None):
            return []
        try:
            current_id = int(self.current_user_id)
            try:
                contact_id = int(contact_id)
            except (ValueError, TypeError):
                log_debug(f"[CHAT GET ERROR] contact_id no es int: {contact_id} ({type(contact_id).__name__})")
                return []
            log_debug(f"[CHAT GET] Buscando mensajes: usuario={current_id}, contacto={contact_id}")
            conn_str = f"DRIVER={DB_DRIVER};SERVER={DB_SERVER};DATABASE={DB_NAME};UID={DB_USER};PWD={DB_PASSWORD};"
            conn = pyodbc.connect(conn_str)
            cur = conn.cursor()
            query = """
            SELECT TOP 500 ID_REMITENTE, ID_DESTINATARIO, MENSAJE, FECHA_ENVIO
            FROM CHAT_MENSAJES
            WHERE (ID_REMITENTE = ? AND ID_DESTINATARIO = ?)
               OR (ID_REMITENTE = ? AND ID_DESTINATARIO = ?)
            ORDER BY FECHA_ENVIO ASC
            """
            cur.execute(query, (current_id, contact_id, contact_id, current_id))
            rows = cur.fetchall()
            log_debug(f"[CHAT GET] ✓ Recuperados {len(rows)} mensaje(s)")
            update_query = """
            UPDATE CHAT_MENSAJES 
            SET LEIDO = 1 
            WHERE ID_DESTINATARIO = ? AND ID_REMITENTE = ? AND LEIDO = 0
            """
            cur.execute(update_query, (current_id, contact_id))
            conn.commit()
            cur.close()
            conn.close()
            return [(int(row[0]), int(row[1]), row[2], row[3]) for row in rows]
        except Exception as e:
            log_debug(f"Error obteniendo mensajes de chat: {e}")
            current_id = str(self.current_user_id)
            contact_id = str(contact_id)
            key = tuple(sorted([current_id, contact_id]))
            return self._chat_history.get(key, [])

    def archive_chat_messages(self, usuario_id=None):
        """Archiva los mensajes de chat a archivos TXT y luego los borra de la BD."""
        try:
            archive_dir = os.path.join(os.path.dirname(__file__), "chat_archives")
            if not os.path.exists(archive_dir):
                os.makedirs(archive_dir)
            conn_str = f"DRIVER={DB_DRIVER};SERVER={DB_SERVER};DATABASE={DB_NAME};UID={DB_USER};PWD={DB_PASSWORD};"
            conn = pyodbc.connect(conn_str)
            cur = conn.cursor()
            if usuario_id:
                usuario_id = int(usuario_id)
                query = """
                SELECT DISTINCT 
                    CASE 
                        WHEN ID_REMITENTE = ? THEN ID_DESTINATARIO 
                        ELSE ID_REMITENTE 
                    END as otro_usuario
                FROM CHAT_MENSAJES
                WHERE ID_REMITENTE = ? OR ID_DESTINATARIO = ?
                """
                cur.execute(query, (usuario_id, usuario_id, usuario_id))
                contactos = [row[0] for row in cur.fetchall()]
            else:
                contactos = None
            cur.execute("SELECT NOMBRE_USUARIO FROM USUARIOS WHERE ID_USUARIO = ?", (usuario_id,))
            user_row = cur.fetchone()
            user_name = user_row[0] if user_row else f"Usuario_{usuario_id}"
            if usuario_id:
                for contact_id in contactos:
                    self._archive_single_conversation(archive_dir, usuario_id, contact_id, user_name, cur)
            conn.commit()
            cur.close()
            conn.close()
            log_debug(f"Chat archivado para usuario {usuario_id}")
            return True
        except Exception as e:
            log_debug(f"Error archivando chat: {e}")
            return False
    
    def _archive_single_conversation(self, archive_dir, user_id1, user_id2, user_name, cur):
        """Archiva una conversación individual a un archivo TXT."""
        try:
            cur.execute("SELECT NOMBRE_USUARIO FROM USUARIOS WHERE ID_USUARIO = ?", (user_id2,))
            other_row = cur.fetchone()
            other_name = other_row[0] if other_row else f"Usuario_{user_id2}"
            query = """
            SELECT ID_REMITENTE, MENSAJE, FECHA_ENVIO
            FROM CHAT_MENSAJES
            WHERE (ID_REMITENTE = ? AND ID_DESTINATARIO = ?)
               OR (ID_REMITENTE = ? AND ID_DESTINATARIO = ?)
            ORDER BY FECHA_ENVIO ASC
            """
            cur.execute(query, (user_id1, user_id2, user_id2, user_id1))
            mensajes = cur.fetchall()
            if not mensajes:
                return
            fecha_hoy = datetime.now().strftime("%Y-%m-%d")
            archivo_nombre = f"Chat_{user_name}-{other_name}_{fecha_hoy}.txt"
            archivo_path = os.path.join(archive_dir, archivo_nombre)
            with open(archivo_path, 'a', encoding='utf-8') as f:
                f.write(f"\n{'='*60}\n")
                f.write(f"Conversación: {user_name} ↔ {other_name}\n")
                f.write(f"Fecha de archivo: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}\n")
                f.write(f"{'='*60}\n\n")
                for remitente_id, mensaje, fecha in mensajes:
                    remitente_nombre = user_name if remitente_id == user_id1 else other_name
                    fecha_str = fecha.strftime("%Y-%m-%d %H:%M:%S") if fecha else "N/A"
                    f.write(f"[{fecha_str}] {remitente_nombre}: {mensaje}\n")
            log_debug(f"Conversación archivada en: {archivo_path}")
        except Exception as e:
            log_debug(f"Error archivando conversación individual: {e}")
    
    def cleanup_old_chat_messages(self, hours=24):
        """Limpia mensajes de chat más antiguos que X horas."""
        try:
            conn_str = f"DRIVER={DB_DRIVER};SERVER={DB_SERVER};DATABASE={DB_NAME};UID={DB_USER};PWD={DB_PASSWORD};"
            conn = pyodbc.connect(conn_str)
            cur = conn.cursor()
            query = """
            DELETE FROM CHAT_MENSAJES
            WHERE FECHA_ENVIO < DATEADD(HOUR, -?, GETDATE())
            """
            cur.execute(query, (hours,))
            deleted_count = cur.rowcount
            conn.commit()
            cur.close()
            conn.close()
            log_debug(f"Limpiados {deleted_count} mensajes antiguos de chat")
            return True
        except Exception as e:
            log_debug(f"Error limpiando mensajes de chat: {e}")
            return False
    
    def schedule_chat_cleanup(self):
        """Programa la limpieza automática de chats cada cierto tiempo."""
        def cleanup_and_reschedule():
            try:
                # Limpiar mensajes más antiguos de 24 horas
                self.cleanup_old_chat_messages(24)
            except Exception as e:
                log_debug(f"Error en cleanup automático: {e}")
            # Reprogramar para dentro de 1 hora (3600000 ms)
            self._chat_cleanup_timer_id = self.root.after(3600000, cleanup_and_reschedule)
        
        # Primera ejecución después de 5 minutos
        self._chat_cleanup_timer_id = self.root.after(300000, cleanup_and_reschedule)

    def send_chat_message(self, contact_id, message):
        """Guarda un mensaje nuevo en la BD y lo sincroniza entre máquinas."""
        if not contact_id or not getattr(self, 'current_user_id', None):
            log_debug(f"[CHAT SEND] ERROR: contact_id={contact_id}, current_user_id={getattr(self, 'current_user_id', None)}")
            return False
        
        texto = (message or "").strip()
        if not texto:
            return False
        
        try:
            current_id = int(self.current_user_id)
            # Tolerancia: convertir contact_id a int de forma segura
            try:
                contact_id = int(contact_id)
            except (ValueError, TypeError):
                log_debug(f"[CHAT SEND ERROR] contact_id no es int: {contact_id} ({type(contact_id).__name__})")
                return False
            
            log_debug(f"[CHAT SEND] Enviando mensaje: remitente={current_id}, destinatario={contact_id}, msg='{texto[:50]}'")
            
            # Garantizar que tabla existe
            self.ensure_chat_tables()
            
            # Guardar en la BD
            conn_str = f"DRIVER={DB_DRIVER};SERVER={DB_SERVER};DATABASE={DB_NAME};UID={DB_USER};PWD={DB_PASSWORD};"
            conn = pyodbc.connect(conn_str)
            cur = conn.cursor()
            
            insert_query = """
            INSERT INTO CHAT_MENSAJES (ID_REMITENTE, ID_DESTINATARIO, MENSAJE, FECHA_ENVIO, LEIDO)
            VALUES (?, ?, ?, GETDATE(), 0)
            """
            cur.execute(insert_query, (current_id, contact_id, texto))
            rows_affected = cur.rowcount
            conn.commit()
            
            cur.close()
            conn.close()
            
            log_debug(f"[CHAT SEND] ✓ Mensaje guardado: {rows_affected} fila(s) insertada(s)")
            return True
            
        except Exception as e:
            log_debug(f"Error guardando mensaje de chat: {e}")
            # Fallback a memoria local en caso de error
            try:
                current_id = str(self.current_user_id)
                contact_id = str(contact_id)
                key = tuple(sorted([current_id, contact_id]))
                if key not in self._chat_history:
                    self._chat_history[key] = []
                self._chat_history[key].append((current_id, contact_id, texto, datetime.now()))
                return True
            except Exception as e2:
                log_debug(f"Error guardando en memoria local: {e2}")
                return False

    def open_chat_panel(self, parent_window=None):
        """Deshabilita la apertura del panel de chat."""
        return None

    def close_chat_panel(self):
        """Cierra el panel de chat de selección."""
        panel = getattr(self, '_chat_panel', None)
        if panel is not None:
            try:
                panel.destroy()
            except Exception:
                pass
        self._chat_panel = None
        self._chat_selected_contact_id = None
        self._chat_selected_contact_name = None

    def refresh_chat_contacts(self):
        """Rellena la lista de contactos según la búsqueda actual."""
        if not hasattr(self, 'chat_contacts_list'):
            return
        try:
            query = self.chat_search_var.get() if hasattr(self, 'chat_search_var') else ""
            contacts = self.get_chat_contacts(query)
            self.chat_contacts_list.delete(0, tk.END)
            for row in contacts:
                uid, nombre, login = row
                display_name = nombre or login or f"Usuario {uid}"
                self.chat_contacts_list.insert(tk.END, f"{display_name}")
                self.chat_contacts_list.itemconfig(tk.END, {'fg': '#1c1c1c'})
        except Exception as e:
            log_debug(f"Error refrescando contactos de chat: {e}")

    def on_chat_contact_select(self, event):
        """Guarda el contacto seleccionado para abrirlo luego."""
        if not hasattr(self, 'chat_contacts_list'):
            return
        try:
            index = self.chat_contacts_list.curselection()
            if not index:
                return
            selected_text = self.chat_contacts_list.get(index[0])
            contacts = self.get_chat_contacts(self.chat_search_var.get() if hasattr(self, 'chat_search_var') else "")
            match = None
            for row in contacts:
                uid, nombre, login = row
                # Asegurarse que uid es int
                uid = int(uid) if uid else None
                display_name = nombre or login or f"Usuario {uid}"
                if display_name == selected_text:
                    match = (uid, nombre, login)
                    break
            if match:
                self._chat_selected_contact_id = int(match[0])
                self._chat_selected_contact_name = match[1] or match[2] or f"Usuario {match[0]}"
                log_debug(f"[CHAT SELECT] Contacto seleccionado: id={self._chat_selected_contact_id}, nombre={self._chat_selected_contact_name}")
            else:
                log_debug(f"[CHAT SELECT ERROR] No se encontró coincidencia para: {selected_text}")
        except Exception as e:
            log_debug(f"Error seleccionando contacto de chat: {e}")

    def open_selected_contact_chat(self, event=None):
        """Abre un chat separado para el contacto seleccionado."""
        if not getattr(self, '_chat_selected_contact_id', None):
            self.on_chat_contact_select(None)
        if not getattr(self, '_chat_selected_contact_id', None):
            return
        self.open_chat_window(self._chat_selected_contact_id, self._chat_selected_contact_name)

    def ensure_chat_dock(self):
        """Crea la barra inferior de chats minimizados si no existe."""
        if getattr(self, '_chat_dock_frame', None) is not None and getattr(self._chat_dock_frame, 'winfo_exists', lambda: False)():
            return self._chat_dock_frame
        parent = getattr(self, '_chat_main_window', None) or self.root
        if parent is None:
            return None
        frame = tk.Frame(parent, bg="#eef2f7", height=44)
        frame.pack(fill="x", side="bottom")
        self._chat_dock_frame = frame
        return frame

    def add_chat_to_dock(self, contact_id, contact_name):
        """Agrega un botón de chat minimizado a la barra inferior."""
        frame = self.ensure_chat_dock()
        if frame is None:
            return
        if contact_id in self._chat_dock_buttons:
            try:
                btn = self._chat_dock_buttons[contact_id]
                if btn.winfo_exists():
                    btn.config(text=f"⬇ {contact_name}")
                    return
            except Exception:
                pass
        btn = ttk.Button(frame, text=f"⬇ {contact_name}", command=lambda cid=contact_id: self.restore_chat_window(cid))
        btn.pack(side="left", padx=4, pady=6)
        self._chat_dock_buttons[contact_id] = btn

    def remove_chat_from_dock(self, contact_id):
        """Elimina el botón de la barra inferior si existe."""
        btn = self._chat_dock_buttons.pop(contact_id, None)
        if btn is not None:
            try:
                btn.destroy()
            except Exception:
                pass

    def open_chat_window(self, contact_id, contact_name):
        """Abre una ventana independiente de chat para un contacto."""
        if not contact_id:
            return None
        
        # CRÍTICO: Crear tabla de chat si no existe
        self.ensure_chat_tables()
        self.debug_chat_db()  # Verificar qué hay en BD
        log_debug(f"[CHAT INIT] Abriendo chat: usuario_actual={self.current_user_id}, contacto={contact_id}")
        
        existing = self._chat_windows.get(contact_id)
        if existing is not None and getattr(existing, 'winfo_exists', lambda: False)():
            existing.deiconify()
            existing.lift()
            existing.focus_force()
            return existing
        if len(self._chat_windows) >= 5:
            messagebox.showwarning("Chat", "Solo puedes tener hasta 5 chats abiertos a la vez.")
            return None

        win = tk.Toplevel(self._chat_panel or self._chat_main_window or self.root)
        win.title(f"Chat - {contact_name}")
        win.geometry("320x430")
        win.resizable(False, False)
        win.configure(bg="#f5f7fa")
        win.transient(self._chat_main_window or self.root)
        self._chat_windows[contact_id] = win
        self._chat_window_widgets[contact_id] = {"window": win, "contact_name": contact_name}
        self._chat_window_after_ids[contact_id] = None

        header = tk.Frame(win, bg="#5b7a9c", height=44)
        header.pack(fill="x")
        tk.Label(header, text=f"{contact_name}", fg="white", bg="#5b7a9c", font=("Segoe UI", 11, "bold")).pack(side="left", padx=10, pady=10)
        ttk.Button(header, text="—", command=lambda cid=contact_id: self.minimize_chat_window(cid)).pack(side="right", padx=(0, 4), pady=8)
        ttk.Button(header, text="✕", command=lambda cid=contact_id: self.close_chat_window(cid)).pack(side="right", padx=(0, 6), pady=8)

        body = tk.Frame(win, bg="#ffffff")
        body.pack(fill="both", expand=True, padx=8, pady=8)
        self._chat_window_widgets[contact_id]['text'] = tk.Text(body, height=16, wrap="word", bg="#ffffff", fg="#222", font=("Segoe UI", 10), bd=0)
        self._chat_window_widgets[contact_id]['text'].pack(fill="both", expand=True, padx=4, pady=(4, 4))
        self._chat_window_widgets[contact_id]['text'].config(state="disabled")

        bottom = tk.Frame(win, bg="#f3f6fa")
        bottom.pack(fill="x", padx=8, pady=(0, 8))
        entry_var = tk.StringVar()
        self._chat_window_widgets[contact_id]['entry_var'] = entry_var
        entry = ttk.Entry(bottom, textvariable=entry_var, width=25)
        entry.pack(side="left", fill="x", expand=True)
        entry.bind("<Return>", lambda event, cid=contact_id: self.send_chat_window_message(cid))
        ttk.Button(bottom, text="Enviar", command=lambda cid=contact_id: self.send_chat_window_message(cid)).pack(side="left", padx=(6, 0))

        win.protocol("WM_DELETE_WINDOW", lambda cid=contact_id: self.close_chat_window(cid))
        # Reset unread counter for this contact when opening
        try:
            msgs = self.get_chat_messages(contact_id) or []
            self._chat_last_len[contact_id] = len(msgs)
            self._chat_unread_counts.pop(contact_id, None)
            if contact_id in self._chat_dock_buttons:
                try:
                    btn = self._chat_dock_buttons[contact_id]
                    if getattr(btn, 'winfo_exists', lambda: False)():
                        btn.config(text=f"⬇ {contact_name}")
                except Exception:
                    pass
        except Exception:
            pass
        self.refresh_chat_window_conversation(contact_id)
        self.start_chat_window_polling(contact_id)
        return win

    def start_chat_window_polling(self, contact_id):
        """Actualiza la conversación del chat cada pocos segundos."""
        widget = self._chat_window_widgets.get(contact_id, {})
        window = widget.get('window')
        if window is None:
            return
        if self._chat_window_after_ids.get(contact_id) is not None:
            try:
                window.after_cancel(self._chat_window_after_ids[contact_id])
            except Exception:
                pass

        log_debug(f"[CHAT POLLING] Iniciando polling para contacto {contact_id}")
        
        def tick(cid=contact_id):
            w = self._chat_windows.get(cid)
            if w is None or not getattr(w, 'winfo_exists', lambda: False)():
                return
            self.refresh_chat_window_conversation(cid)
            self._chat_window_after_ids[cid] = w.after(1000, tick)

        self._chat_window_after_ids[contact_id] = window.after(1000, tick)

    def refresh_chat_window_conversation(self, contact_id):
        """Actualiza la vista del chat abierto."""
        widget = self._chat_window_widgets.get(contact_id)
        if not widget:
            return
        text_widget = widget.get('text')
        if text_widget is None:
            return
        try:
            messages = self.get_chat_messages(contact_id)
            log_debug(f"[CHAT REFRESH] Renderizando {len(messages)} mensajes para contacto {contact_id}")
            text_widget.config(state="normal")
            text_widget.delete("1.0", tk.END)
            if not messages:
                text_widget.insert(tk.END, "Aún no hay mensajes. Escribe uno para comenzar.")
            else:
                prev_len = int(self._chat_last_len.get(contact_id, 0))
                new_len = len(messages)
                # Render messages
                for emisor, receptor, mensaje, fecha in messages:
                    current_id = int(self.current_user_id)
                    author = "Tú" if int(emisor) == current_id else widget.get('contact_name', "Contacto")
                    stamp = str(fecha) if fecha else ""
                    text_widget.insert(tk.END, f"[{stamp}] {author}: {mensaje}\n")
                # Update unread counters / dock notifications
                try:
                    win = widget.get('window')
                    visible = win is not None and getattr(win, 'winfo_exists', lambda: False)() and win.state() != 'iconic'
                except Exception:
                    visible = False
                if new_len > prev_len and not visible:
                    unread = new_len - prev_len
                    self._chat_unread_counts[contact_id] = unread
                    # ensure dock button exists and show count
                    try:
                        if contact_id not in self._chat_dock_buttons:
                            self.add_chat_to_dock(contact_id, widget.get('contact_name', f'Chat {contact_id}'))
                        btn = self._chat_dock_buttons.get(contact_id)
                        if btn is not None and getattr(btn, 'winfo_exists', lambda: False)():
                            btn.config(text=f"⬇ {widget.get('contact_name','Contacto')} ({unread})")
                    except Exception:
                        pass
                else:
                    # clear unread if visible or no change
                    self._chat_unread_counts.pop(contact_id, None)
                    self._chat_last_len[contact_id] = new_len
                    # remove dock button if present
                    try:
                        if contact_id in self._chat_dock_buttons:
                            btn = self._chat_dock_buttons[contact_id]
                            if getattr(btn, 'winfo_exists', lambda: False)():
                                btn.config(text=f"⬇ {widget.get('contact_name','Contacto')}")
                    except Exception:
                        pass
            text_widget.config(state="disabled")
            text_widget.see(tk.END)
        except Exception as e:
            log_debug(f"Error refrescando conversación del chat: {e}")

    def send_chat_window_message(self, contact_id):
        """Envía un mensaje desde la ventana independiente de chat."""
        widget = self._chat_window_widgets.get(contact_id)
        if not widget:
            log_debug(f"[CHAT SEND ERROR] Widget no encontrado para contacto {contact_id}")
            return
        entry_var = widget.get('entry_var')
        mensaje = entry_var.get().strip() if entry_var is not None else ""
        if not mensaje:
            log_debug(f"[CHAT SEND ERROR] Mensaje vacío")
            return
        
        log_debug(f"[CHAT SEND ATTEMPT] Enviando '{mensaje[:50]}' a contacto {contact_id}")
        
        if self.send_chat_message(contact_id, mensaje):
            log_debug(f"[CHAT SEND SUCCESS] Mensaje enviado, limpiando input y refrescando")
            entry_var.set("")
            # Refrescar inmediatamente después de enviar
            self.root.after(100, lambda: self.refresh_chat_window_conversation(contact_id))
        else:
            log_debug(f"[CHAT SEND FAILED] Error al guardar mensaje en BD")
            messagebox.showerror("Chat", "No se pudo enviar el mensaje.")

    def minimize_chat_window(self, contact_id):
        """Minimiza el chat a la barra inferior."""
        widget = self._chat_window_widgets.get(contact_id)
        if not widget:
            return
        window = widget.get('window')
        if window is None or not getattr(window, 'winfo_exists', lambda: False)():
            return
        contact_name = widget.get('contact_name', f"Chat {contact_id}")
        window.withdraw()
        self.add_chat_to_dock(contact_id, contact_name)

    def restore_chat_window(self, contact_id):
        """Restaura un chat minimizado desde la barra inferior."""
        widget = self._chat_window_widgets.get(contact_id)
        if not widget:
            return
        window = widget.get('window')
        if window is None or not getattr(window, 'winfo_exists', lambda: False)():
            return
        self.remove_chat_from_dock(contact_id)
        window.deiconify()
        window.lift()
        window.focus_force()

    def close_chat_window(self, contact_id):
        """Cierra un chat específico y limpia su estado."""
        widget = self._chat_window_widgets.pop(contact_id, None)
        self._chat_windows.pop(contact_id, None)
        self.remove_chat_from_dock(contact_id)
        after_id = self._chat_window_after_ids.pop(contact_id, None)
        if after_id is not None:
            try:
                window = widget.get('window') if widget else None
                if window is not None:
                    window.after_cancel(after_id)
            except Exception:
                pass
        if widget is not None:
            window = widget.get('window')
            if window is not None and getattr(window, 'winfo_exists', lambda: False)():
                try:
                    window.destroy()
                except Exception:
                    pass

    def open_main_window(self, usuario_id, nombre, id_departamento, nivel):
        """Ventana principal simplificada según rol/área."""
        if hasattr(self, '_cached_permissions') and self._cached_permissions is not None:
            perms = self._cached_permissions
        else:
            perms = self.get_user_permissions(usuario_id, id_departamento)
            self._cached_permissions = perms
        win = tk.Toplevel(self.root)
        try:
            if not getattr(self, '_internal_show_falla_editor', None) or not callable(getattr(self, '_internal_show_falla_editor', None)):
                self._internal_show_falla_editor = None
        except Exception:
            self._internal_show_falla_editor = None
        try:
            if not getattr(self, '_show_order_editor', None) or not callable(getattr(self, '_show_order_editor', None)):
                self._show_order_editor = None
        except Exception:
            self._show_order_editor = None
        win.title(f"Principal - {nombre}")
        win.state('zoomed')
        win.minsize(1000, 700)
        win.configure(bg=self.bg)
        header = tk.Frame(win, bg=self.bg, height=80)
        header.pack(fill="x", side="top")
        header_bg_img = None
        bg_img_path = get_resource_path("fondo_inicio.png")
        if os.path.exists(bg_img_path) and PIL_AVAILABLE:
            try:
                img = Image.open(bg_img_path)
                img_resized = img.resize((1920, 100), Image.Resampling.LANCZOS)
                header_bg_img = ImageTk.PhotoImage(img_resized)
                bg_label = tk.Label(header, image=header_bg_img)
                bg_label.image = header_bg_img
                bg_label.place(x=0, y=0, relwidth=1, relheight=1)
            except Exception as e:
                print(f"No se pudo cargar imagen de fondo del header: {e}")
        win.header_bg_img = header_bg_img
        header_inner = tk.Frame(header, highlightthickness=0)
        header_inner.pack(fill="both", expand=True, padx=12, pady=10)
        user_info_frame = tk.Frame(header_inner, bg="#ffffff", highlightthickness=0)
        user_info_frame.pack(side="left", fill="both", expand=True, padx=6)
        tk.Label(user_info_frame, text=f"Usuario: {nombre}", bg="#ffffff", fg=self.accent, 
                font=("Segoe UI", 12, "bold")).pack(side="left", padx=12, pady=8)
        dep_label = getattr(self, "current_dep_name", "")
        tk.Label(user_info_frame, text=f"Departamento: {dep_label}", bg="#ffffff", fg=self.text_color,
                font=("Segoe UI", 11)).pack(side="left", padx=12, pady=8)
        # Mostrar selector de turno en la barra superior para personal de mantenimiento/sistemas
        try:
            if self.is_maintenance_or_systems():
                turno_frame = tk.Frame(user_info_frame, bg="#ffffff", highlightthickness=0)
                turno_frame.pack(side='left', padx=(6,0), pady=8)
                
                header_turno_var = tk.StringVar(value="Cargando...")
                header_turno_combo = ttk.Combobox(turno_frame, textvariable=header_turno_var, state='readonly', width=18, font=("Segoe UI", 10))
                header_turno_combo.pack(side='left', padx=(0,4))
                
                def save_turno_clicked():
                    sel = (header_turno_var.get() or '').strip()
                    if not sel or sel in ('Seleccionar', 'Cargando...'):
                        try:
                            self.create_error_window('✗ Atención', 'Por favor selecciona un turno válido')
                        except Exception:
                            pass
                        return
                    try:
                        uid = getattr(self, 'current_user_id', None)
                        ok = self.save_user_turno_to_db(uid, turno_nombre=sel)
                        if ok:
                            try:
                                self.create_success_window('✓ Éxito', f'Turno cambiado correctamente al {sel}', duration_ms=2500)
                            except Exception as e:
                                log_debug(f"Error mostrando ventana de éxito: {e}")
                        else:
                            try:
                                self.create_error_window('✗ Error', f'No se pudo guardar el turno {sel}. Por favor intenta de nuevo.')
                            except Exception as e:
                                log_debug(f"Error mostrando ventana de error: {e}")
                    except Exception as e:
                        try:
                            self.create_error_window('✗ Error', f'Ocurrió un error al guardar el turno: {str(e)[:50]}')
                        except Exception:
                            pass
                        log_debug(f"Error guardando turno: {e}")
                
                # Botón pequeño con palomita para guardar
                save_btn = tk.Button(turno_frame, text="✓", command=save_turno_clicked, 
                                    bg="#4CAF50", fg="white", font=("Segoe UI", 11, "bold"),
                                    width=2, height=1, relief="raised", bd=1, cursor="hand2")
                save_btn.pack(side='left', padx=(0,8))
                
                def load_header_turnos():
                    try:
                        cfg = {"host": DB_SERVER, "user": DB_USER, "password": DB_PASSWORD, "database": DB_NAME}
                        conn = mysql.connect(**cfg)
                        cur = conn.cursor()
                        cur.execute("SELECT DISTINCT NOMBRE_TURNO FROM TURNOS ORDER BY NOMBRE_TURNO")
                        turnos = [row[0] for row in cur.fetchall()]
                        # Preparar valores del combobox
                        vals = ["Seleccionar"] + (turnos if turnos else [])
                        header_turno_combo['values'] = vals
                        header_turno_combo.config(state='readonly')
                        # Intentar obtener turno actual del usuario directamente desde la BD
                        uid = getattr(self, 'current_user_id', None)
                        nombre_turno = ''
                        if uid:
                            try:
                                # Obtener ID_TURNO del usuario
                                cur.execute("SELECT ID_TURNO FROM USUARIOS WHERE ID_USUARIO = %s", (uid,))
                                row = cur.fetchone()
                                if row and row[0]:
                                    id_turno = row[0]
                                    # Obtener NOMBRE_TURNO de la tabla TURNOS
                                    try:
                                        cur.execute("SELECT NOMBRE_TURNO FROM TURNOS WHERE ID_TURNO = %s", (id_turno,))
                                        r = cur.fetchone()
                                        if r and r[0]:
                                            nombre_turno = r[0]
                                    except Exception as e:
                                        log_debug(f"Error obteniendo nombre del turno: {e}")
                                if nombre_turno and nombre_turno in vals:
                                    header_turno_var.set(str(nombre_turno))
                                else:
                                    header_turno_var.set('Seleccionar')
                            except Exception as e:
                                log_debug(f"Error obteniendo turno del usuario {uid}: {e}")
                                header_turno_var.set('Seleccionar')
                        else:
                            header_turno_var.set('Seleccionar')
                        cur.close(); conn.close()
                    except Exception as e:
                        log_debug(f"Error en load_header_turnos: {e}")
                        try:
                            header_turno_combo['values'] = ["Seleccionar"]
                            header_turno_combo.config(state='disabled')
                            header_turno_var.set('Seleccionar')
                        except Exception:
                            pass
                def trigger_header_turnos_load():
                    try:
                        load_header_turnos()
                    except Exception:
                        pass

                self.root.after(100, trigger_header_turnos_load)
        except Exception:
            pass
        logout_frame = tk.Frame(header_inner, bg="#ffffff", highlightthickness=0)
        logout_frame.pack(side="right", padx=6)
        def do_logout():
            try:
                # Archivar chats del usuario antes de borrar su sesión
                uid = getattr(self, 'current_user_id', None)
                if uid:
                    try:
                        self.archive_chat_messages(uid)
                    except Exception as e:
                        log_debug(f"Error archivando chats al logout: {e}")
                try:
                    self.log_action(getattr(self, 'current_user_id', None) or 0, 'LOGOUT - Cerrar sesión')
                except Exception:
                    pass
            finally:
                self.current_session_id = None
                self.current_session_token = None
                self.current_user_id = None
                self.current_user_name = ''
                self.current_dep_id = None
                self.current_dep_name = ''
                self.is_admin = False
