        def load_maquinas_catalogo():
            try:
                cfg = {"host": DB_SERVER, "user": DB_USER, "password": DB_PASSWORD, "database": DB_NAME}
                conn = mysql.connect(**cfg)
                cur = conn.cursor()
                cur.execute("SELECT m.ID_MAQUINA, d.NOMBRE_ROL, m.NOMBRE_MAQUINA, m.ESTADO, COALESCE(m.DESCRIPCION,'') FROM MAQUINAS m LEFT JOIN DEPARTAMENTOS d ON m.ID_DEPARTAMENTO=d.ID_DEPARTAMENTO ORDER BY d.NOMBRE_ROL, m.NOMBRE_MAQUINA")
                rows = cur.fetchall()
                cur.close()
                conn.close()
                estado_map = {'A': 'Activo', 'M': 'Mantenimiento', 'I': 'Inactivo', 'a': 'Activo', 'm': 'Mantenimiento', 'i': 'Inactivo'}
                for r in tree_maquinas.get_children():
                    tree_maquinas.delete(r)
                for row in rows:
                    estado_completo = estado_map.get(row[3], row[3])
                    v0 = clean_cell(row[0])
                    v1 = clean_cell(row[1])
                    v2 = clean_cell(row[2])
                    v3 = clean_cell(estado_completo)
                    tree_maquinas.insert("", "end", values=(v0, v1, v2, v3))
            except Exception:
                traceback.print_exc()
