        last_valid_tab = [0]
        def on_main_notebook_changed(event=None):
            """Verifica permisos cuando cambia de pestaña principal."""
            try:
                tab_index = main_notebook.index("current")
                current_tab_id = main_notebook.select()
                tab_text = str(main_notebook.tab(current_tab_id, "text") or "").strip()
                tiene_permiso = True
                razon = ""
                tab_label = tab_text or "esta pestaña"
                if "Seguridad" in tab_text:
                    tiene_permiso = self.is_admin or getattr(self, 'is_admin_login', False)
                    if not tiene_permiso:
                        razon = "Solo administradores pueden acceder a Seguridad"
                elif "Bitácora" in tab_text or "Bitacora" in tab_text:
                    tiene_permiso = can_view_principal_bitacora
                    if not tiene_permiso:
                        razon = "No tiene permisos para acceder a Bitácora"
                if not tiene_permiso:
                    messagebox.showwarning("❌ Acceso Denegado",
                                          f"No tiene permisos para acceder a {tab_label}.\n\n{razon}",
                                          parent=win)
                    main_notebook.select(last_valid_tab[0])
                    return
                last_valid_tab[0] = tab_index
            except Exception as e:
                log_debug(f"Error en validación de permisos: {e}")
        main_notebook.bind("<<NotebookTabChanged>>", on_main_notebook_changed)
