            sel_box = tk.Frame(chk_frame, bg="#e8ecf1", bd=1, relief='solid', padx=12, pady=10)
            sel_box.grid(row=0, column=0, columnspan=cols, sticky='ew', padx=8, pady=(8,12))
            sel_cb = tk.Checkbutton(sel_box, text="Seleccionar todos", variable=sel_all_var, command=toggle_all, bg="#e8ecf1", fg=self.accent, font=("Segoe UI",11,"bold"), activebackground="#dde5f0", selectcolor="#dde5f0")
