                                    sql = f"SELECT ID_USUARIO, NOMBRE_USUARIO FROM USUARIOS WHERE ID_DEPARTAMENTO IN ({placeholders}) ORDER BY NOMBRE_USUARIO"
                                    cur2.execute(sql, tuple(deps))
