            def on_select_edit(event=None):
                sel = tv.selection()
                if not sel:
                    return
                vals = tv.item(sel[0], "values")
                uid = vals[0]
                editing_id[0] = uid
                nombre_editar_var.set(vals[1])
                login_editar_var.set(vals[2])
                dept_id = vals[3] or ""
                id_by_name = {id: name for name, id in dep_by_name.items()}
                dept_name = id_by_name.get(dept_id, "") or ""
                dept_editar_var.set(dept_name)
                estado_editar_var.set(vals[4] or "")
                try:
                    cfg = {"host": DB_SERVER, "user": DB_USER, "password": DB_PASSWORD, "database": DB_NAME}
                    conn2 = mysql.connect(**cfg)
                    cur2 = conn2.cursor()
                    if self.table_has_column('usuarios', 'nivel'):
                        cur2.execute("SELECT COALESCE(password_hash,''), COALESCE(cargo,''), COALESCE(nivel, 1) FROM usuarios WHERE id_usuario=%s", (uid,))
                    else:
                        cur2.execute("SELECT COALESCE(password_hash,''), COALESCE(cargo,'') FROM usuarios WHERE id_usuario=%s", (uid,))
                    rr = cur2.fetchone()
                    if rr:
                        password_anterior[0] = rr[0] or ""
                        pwd_editar_var.set("")
                        cargo_editar_var.set(rr[1] or "")
                        if len(rr) > 2:
                            role_editar_var.set("Administrador" if int(rr[2] or 1) >= 10 else "Usuario Regular")
                    turno_id_edit[0] = None
                    turno_editar_var.set("Seleccionar")
                    if self.table_has_column('usuarios', 'ID_TURNO'):
                        try:
                            cur2.execute("SELECT COALESCE(ID_TURNO, NULL) FROM usuarios WHERE id_usuario=%s", (uid,))
                            turno_row = cur2.fetchone()
                            if turno_row and turno_row[0] is not None:
                                turno_id_edit[0] = turno_row[0]
                                cur2.execute("SELECT NOMBRE_TURNO FROM TURNOS WHERE ID_TURNO = %s", (turno_id_edit[0],))
                                nombre_turno = cur2.fetchone()
                                if nombre_turno and nombre_turno[0]:
                                    turno_editar_var.set(str(nombre_turno[0]))
                        except Exception:
                            pass
                    elif self.table_has_column('usuarios', 'TURNO'):
                        try:
                            cur2.execute("SELECT COALESCE(TURNO, '') FROM usuarios WHERE id_usuario=%s", (uid,))
                            turno_row = cur2.fetchone()
                            if turno_row and turno_row[0]:
                                turno_editar_var.set(str(turno_row[0]))
                        except Exception:
                            pass
                    cur2.close(); conn2.close()
                except Exception:
                    password_anterior[0] = None
                    pwd_editar_var.set("")
                    cargo_editar_var.set("")
                    role_editar_var.set("Usuario Regular")
