            def on_save_editar():
                if not editing_id[0]:
                    messagebox.showwarning("Seleccionar", "Seleccione un usuario de la tabla.", parent=tab_editar_usuario)
                    return
                nombre = nombre_editar_var.get().strip()
                login = login_editar_var.get().strip()
                pwd = pwd_editar_var.get()
                role = role_editar_var.get()
                estado_v = estado_editar_var.get() or "activo"
                nivel_v = 10 if role == "Administrador" else 1
                if role == "Administrador":
                    dept_v = None
                    cargo = "Administrador"
                    turno_v = None
                else:
                    dept_name = dept_editar_var.get()
                    dept_v = dep_by_name.get(dept_name)
                    cargo = cargo_editar_var.get().strip()
                    turno_v = turnos_map.get(turno_editar_var.get())
                    if not dept_v:
                        messagebox.showwarning("Validación", "Debe seleccionar un departamento.", parent=tab_editar_usuario)
                        return
                if not nombre or not login:
                    messagebox.showwarning("Validación", "Nombre y login son obligatorios.", parent=tab_editar_usuario)
                    return
                pwd_to_save = password_anterior[0]
                if pwd:
                    pwd_to_save = hashlib.sha256(pwd.encode("utf-8")).hexdigest()
                try:
                    cfg = {"host": DB_SERVER, "user": DB_USER, "password": DB_PASSWORD, "database": DB_NAME}
                    conn = mysql.connect(**cfg)
                    cur = conn.cursor()
                    update_fields = ["nombre_usuario=%s", "usuario_login=%s", "password_hash=%s", "estado=%s", "cargo=%s"]
                    params = [nombre, login, pwd_to_save, estado_v, cargo]
                    if role != "Administrador":
                        update_fields.append("id_departamento=%s")
                        params.append(dept_v)
                    if self.table_has_column('usuarios', 'nivel'):
                        update_fields.append("nivel=%s")
                        params.append(nivel_v)
                    if self.table_has_column('usuarios', 'ID_TURNO'):
                        update_fields.append("ID_TURNO=%s")
                        params.append(turno_v)
                    params.append(editing_id[0])
                    sql = f"UPDATE usuarios SET {', '.join(update_fields)} WHERE id_usuario=%s"
                    cur.execute(sql, tuple(params))
                    conn.commit()
                    cur.close()
                    conn.close()
                    self.log_action(self.current_user_id, f"Editar usuario: {login} (ID {editing_id[0]})")
                    messagebox.showinfo("OK", "Usuario actualizado correctamente.", parent=tab_editar_usuario)
                    load_users_tab()
                except Exception as e:
                    messagebox.showerror("Error BD", f"No se pudo actualizar usuario:\n{e}", parent=tab_editar_usuario)
            btns_editar = tk.Frame(frame_editar)
