            ttk.Button(btns_editar, text="Guardar cambios", command=on_save_editar, style="Accent.TButton").pack(side="left", padx=(0,6))
            ttk.Button(btns_editar, text="Cancelar", command=lambda: (nombre_editar_var.set(""), login_editar_var.set(""), pwd_editar_var.set(""), role_editar_var.set("Usuario Regular"), dept_editar_var.set(""), cargo_editar_var.set(""), estado_editar_var.set(""), editing_id.__setitem__(0, None), update_fields_visibility_edit()), style="Action.TButton").pack(side="left")
            frame_eliminar = tk.Frame(nb, padx=10, pady=10)
            nb.add(frame_eliminar, text="Eliminar")
            tk.Label(frame_eliminar, text="Nombre", anchor="w", font=("Segoe UI", 9, "bold")).pack(fill="x", pady=(4,0))
            nombre_eliminar_var = tk.StringVar()
