            nombre_eliminar.pack(fill="x", pady=4)
            tk.Label(frame_eliminar, text="Login", anchor="w", font=("Segoe UI", 9, "bold")).pack(fill="x", pady=(8,0))
            login_eliminar_var = tk.StringVar()
            login_eliminar = ttk.Entry(frame_eliminar, textvariable=login_eliminar_var, width=28, state="readonly")
            login_eliminar.pack(fill="x", pady=4)
            tk.Label(frame_eliminar, text="Departamento", anchor="w", font=("Segoe UI", 9, "bold")).pack(fill="x", pady=(8,0))
            dept_eliminar_var = tk.StringVar()
            dept_eliminar = ttk.Entry(frame_eliminar, textvariable=dept_eliminar_var, width=28, state="readonly")
            dept_eliminar.pack(fill="x", pady=4)
            tk.Label(frame_eliminar, text="Estado", anchor="w", font=("Segoe UI", 9, "bold")).pack(fill="x", pady=(8,0))
            estado_eliminar_var = tk.StringVar()
            estado_eliminar = ttk.Entry(frame_eliminar, textvariable=estado_eliminar_var, width=28, state="readonly")
            estado_eliminar.pack(fill="x", pady=4)
            tk.Label(frame_eliminar, text="Turno", anchor="w", font=("Segoe UI", 9, "bold")).pack(fill="x", pady=(8,0))
            turno_eliminar_var = tk.StringVar()
            turno_eliminar = ttk.Entry(frame_eliminar, textvariable=turno_eliminar_var, width=28, state="readonly")
            turno_eliminar.pack(fill="x", pady=4)
            eliminar_id = [None]
            def on_select_para_eliminar(event=None):
                sel = tv.selection()
                if not sel:
                    nombre_eliminar_var.set("")
                    login_eliminar_var.set("")
                    dept_eliminar_var.set("")
                    estado_eliminar_var.set("")
                    eliminar_id[0] = None
                    return
                vals = tv.item(sel[0], "values")
                uid = vals[0]
                eliminar_id[0] = uid
                nombre_eliminar_var.set(vals[1])
                login_eliminar_var.set(vals[2])
                dept_eliminar_var.set(vals[3] or "")
                estado_eliminar_var.set(vals[4] or "")
                turno_name = ""
                if self.table_has_column('usuarios', 'ID_TURNO'):
                    try:
                        cfg = {"host": DB_SERVER, "user": DB_USER, "password": DB_PASSWORD, "database": DB_NAME}
                        conn4 = mysql.connect(**cfg)
                        cur4 = conn4.cursor()
                        cur4.execute("SELECT COALESCE(ID_TURNO, NULL) FROM usuarios WHERE id_usuario=%s", (uid,))
                        row_t = cur4.fetchone()
                        if row_t and row_t[0] is not None:
                            cur4.execute("SELECT NOMBRE_TURNO FROM TURNOS WHERE ID_TURNO = %s", (row_t[0],))
                            rr = cur4.fetchone()
                            if rr and rr[0]:
                                turno_name = str(rr[0])
                        cur4.close()
                        conn4.close()
                    except Exception:
                        turno_name = ""
                elif self.table_has_column('usuarios', 'TURNO'):
                    try:
                        cfg = {"host": DB_SERVER, "user": DB_USER, "password": DB_PASSWORD, "database": DB_NAME}
                        conn4 = mysql.connect(**cfg)
                        cur4 = conn4.cursor()
                        cur4.execute("SELECT COALESCE(TURNO,'') FROM usuarios WHERE id_usuario=%s", (uid,))
                        rr = cur4.fetchone()
                        if rr and rr[0]:
                            turno_name = str(rr[0])
                        cur4.close(); conn4.close()
                    except Exception:
                        turno_name = ""
                turno_eliminar_var.set(turno_name)
            def on_delete():
                if not eliminar_id[0]:
                    messagebox.showwarning("Seleccionar", "Seleccione un usuario de la tabla para eliminar.", parent=tab_editar_usuario)
                    return
                confirm = messagebox.askyesno("Confirmar eliminación", f"¿Está seguro de que desea eliminar al usuario?\n\nNombre: {nombre_eliminar_var.get()}\nLogin: {login_eliminar_var.get()}\n\nEsta acción no se puede deshacer.", parent=tab_editar_usuario)
                if not confirm:
                    return
                try:
                    cfg = {"host": DB_SERVER, "user": DB_USER, "password": DB_PASSWORD, "database": DB_NAME}
                    conn = mysql.connect(**cfg)
                    cur = conn.cursor()
                    cur.execute("DELETE FROM LOGS WHERE ID_USUARIO = %s", (eliminar_id[0],))
                    cur.execute("DELETE FROM usuarios WHERE id_usuario=%s", (eliminar_id[0],))
                    conn.commit()
                    cur.close()
                    conn.close()
                    self.log_action(self.current_user_id, f"Eliminar usuario (tab): {login_eliminar_var.get()} (ID {eliminar_id[0]})")
                    messagebox.showinfo("OK", "Usuario eliminado correctamente.", parent=tab_editar_usuario)
                    load_users_tab()
                    nombre_eliminar_var.set("")
                    login_eliminar_var.set("")
                    dept_eliminar_var.set("")
                    estado_eliminar_var.set("")
                    eliminar_id[0] = None
                except Exception as e:
                    messagebox.showerror("Error BD", f"No se pudo eliminar usuario:\n{e}", parent=tab_editar_usuario)
            btns_eliminar = tk.Frame(frame_eliminar)
            btns_eliminar.pack(fill="x", pady=12)
            ttk.Button(btns_eliminar, text="Eliminar usuario", command=on_delete, style="Accent.TButton").pack(side="left", padx=(0,6))
            ttk.Button(btns_eliminar, text="Cancelar", command=lambda: (nombre_eliminar_var.set(""), login_eliminar_var.set(""), dept_eliminar_var.set(""), estado_eliminar_var.set(""), eliminar_id.__setitem__(0, None)), style="Action.TButton").pack(side="left")
            frame_editar.on_select_para_eliminar = on_select_para_eliminar
            bind_mousewheel_to_canvas(right_inner, right_canvas)
            def load_users_tab():
                """Cargar usuarios de la BD al treeview."""
                for i in tv.get_children():
                    tv.delete(i)
                try:
                    cfg = {"host": DB_SERVER, "user": DB_USER, "password": DB_PASSWORD, "database": DB_NAME}
                    conn = mysql.connect(**cfg)
                    cur = conn.cursor()
                    cur.execute("""
                        SELECT 
                            u.ID_USUARIO, 
                            u.NOMBRE_USUARIO, 
                            u.USUARIO_LOGIN, 
                            u.ID_DEPARTAMENTO, 
                            u.ESTADO 
                        FROM usuarios u 
                        ORDER BY u.NOMBRE_USUARIO
                    """)
                    for r in cur.fetchall():
                        id_usr = str(r[0]).strip().strip("'\"()") if r[0] else ""
                        nombre = str(r[1]).strip().strip("'\"()") if r[1] else ""
                        login = str(r[2]).strip().strip("'\"()") if r[2] else ""
                        depto = str(r[3]).strip().strip("'\"()") if r[3] else ""
                        estado = str(r[4]).strip().strip("'\"()") if r[4] else ""
                        tv.insert("", "end", values=(id_usr, nombre, login, depto, estado))
                    cur.close()
                    conn.close()
                except Exception as e:
                    messagebox.showerror("Error BD", f"No se pudieron cargar usuarios:\n{e}", parent=tab_editar_usuario)
            tv.bind("<<TreeviewSelect>>", lambda e: (on_select_edit(e), on_select_para_eliminar(e)))
            load_users_tab()
