                                        seg_data_merged['INICIO'] = tm_values[0]
                                        seg_data_merged['HORA_INICIO'] = tm_values[1] if len(tm_values) > 1 else None
                                        seg_data_merged['TERMINADO'] = tm_values[2]
                                        seg_data_merged['HORA_TERMINO'] = tm_values[3] if len(tm_values) > 3 else None
                                        seg_data_merged['RECIBIDO'] = tm_values[4]
                                        seg_data_merged['TIEMPO_MUERTO'] = tm_values[5]
                                        seg_data_merged['TIPO_TIEMPO_MUERTO'] = tm_values[6]
