                                _atiende_join = ""
                                if 'ID_ATIENDE' in ordenes_fallas_cols:
                                    _atiende_sel = f", ofl.ID_ATIENDE, COALESCE(ua.{usr_col or 'ID_USUARIO'}, '') AS nombre_atiende" if usr_col else ", ofl.ID_ATIENDE, '' AS nombre_atiende"
                                    _atiende_join = f"LEFT JOIN USUARIOS ua ON ofl.ID_ATIENDE = ua.ID_USUARIO" if usr_col else ""
                                cur.execute(f"""
                                    SELECT ofl.ID_FALLA, f.NOMBRE_FALLA, COALESCE(ofl.DESCRIPCION_SOLUCION, '') as solucion{_obs_sel}{_atiende_sel}
                                    FROM ORDENES_FALLAS ofl
                                    LEFT JOIN FALLAS f ON ofl.ID_FALLA = f.ID_FALLA
                                    {_atiende_join}
                                    WHERE ofl.ID_ORDEN = ?
                                    ORDER BY ofl.ID_FALLA
                                """, (orden_id,))
                                todas_fallas = _fetchall_dict(cur)
                                cur.execute("SELECT NOMBRE_FALLA FROM FALLAS WHERE ID_FALLA = ?", (falla_id,))
                                falla_nombre_row = _fetchone_dict(cur)
                                falla_nombre = falla_nombre_row.get('NOMBRE_FALLA') if falla_nombre_row else f"Falla #{falla_id}"
                                cur.close()
                                conn.close()
                                edit_win = tk.Toplevel(panel_frame)
                                try:
                                    edit_win.withdraw()
                                except Exception:
                                    pass
                                edit_win.title(f"Orden #{orden_id} - {falla_nombre}")
                                edit_win.geometry("800x600")
                                edit_win.minsize(600, 400)
                                edit_win.transient(panel_frame)
                                edit_win.grab_set()
                                edit_win.configure(bg="white")
                                parent_win = panel_frame.winfo_toplevel()
                                sync_state = {
                                    "updating": False,
                                    "offset_x": 0,
                                    "offset_y": 0,
                                    "parent_x": None,
                                    "parent_y": None,
                                    "child_x": None,
                                    "child_y": None,
                                    "job": None,
                                }
                                try:
                                    window_width = 800
                                    window_height = 600
                                    center_window(edit_win, width=window_width, height=window_height, parent=None)
                                    parent_x = parent_win.winfo_rootx()
                                    parent_y = parent_win.winfo_rooty()
                                    child_x = edit_win.winfo_rootx()
                                    child_y = edit_win.winfo_rooty()
                                    sync_state["offset_x"] = child_x - parent_x
                                    sync_state["offset_y"] = child_y - parent_y
                                    sync_state["parent_x"] = parent_x
                                    sync_state["parent_y"] = parent_y
                                    sync_state["child_x"] = child_x
                                    sync_state["child_y"] = child_y
                                except Exception:
                                    pass
                                def _apply_child_position():
                                    if sync_state["updating"] or not edit_win.winfo_exists():
                                        return
                                    try:
                                        sync_state["updating"] = True
                                        width = edit_win.winfo_width()
                                        height = edit_win.winfo_height()
                                        parent_x = parent_win.winfo_rootx()
                                        parent_y = parent_win.winfo_rooty()
                                        new_x = max(0, parent_x + sync_state["offset_x"])
                                        new_y = max(0, parent_y + sync_state["offset_y"])
                                        sync_state["parent_x"] = parent_x
                                        sync_state["parent_y"] = parent_y
                                        sync_state["child_x"] = new_x
                                        sync_state["child_y"] = new_y
                                        edit_win.geometry(f"{width}x{height}+{new_x}+{new_y}")
                                    except Exception:
                                        pass
                                    finally:
                                        sync_state["job"] = None
                                        sync_state["updating"] = False
                                def _schedule_sync():
                                    if sync_state["job"] is not None:
                                        try:
                                            edit_win.after_cancel(sync_state["job"])
                                        except Exception:
                                            pass
                                    try:
                                        sync_state["job"] = edit_win.after(20, _apply_child_position)
                                    except Exception:
                                        sync_state["job"] = None
                                def _sync_child_with_parent(_event=None):
                                    if sync_state["updating"] or not edit_win.winfo_exists():
                                        return
                                    try:
                                        parent_x = parent_win.winfo_rootx()
                                        parent_y = parent_win.winfo_rooty()
                                        if parent_x == sync_state["parent_x"] and parent_y == sync_state["parent_y"]:
                                            return
                                        _schedule_sync()
                                    except Exception:
                                        pass
                                def _track_child_position(_event=None):
                                    if sync_state["updating"] or not edit_win.winfo_exists():
                                        return
                                    try:
                                        child_x = edit_win.winfo_rootx()
                                        child_y = edit_win.winfo_rooty()
                                        if child_x == sync_state["child_x"] and child_y == sync_state["child_y"]:
                                            return
                                        sync_state["child_x"] = child_x
                                        sync_state["child_y"] = child_y
                                        sync_state["offset_x"] = child_x - parent_win.winfo_rootx()
                                        sync_state["offset_y"] = child_y - parent_win.winfo_rooty()
                                    except Exception:
                                        pass
                                parent_bind_id = parent_win.bind("<Configure>", _sync_child_with_parent, add="+")
                                edit_win.bind("<Configure>", _track_child_position, add="+")
