                                    import re
                                    def normalize_desc_segment(text):
                                        s = str(text or "").strip()
                                        if not s:
                                            return ""
                                        s = re.sub(r'^\s*\d+\s*-\s*', '', s)
                                        s = re.sub(r'\s+', ' ', s)
                                        return s.strip()
                                    segments = re.split(r'\s*(?:\n{2,}|\r\n{2,}|\s*/\s*)\s*', desc_full)
                                    normalized = [normalize_desc_segment(seg) for seg in segments if seg and seg.strip()]
                                    if normalized:
                                        base_title = ''
                                        first = normalized[0]
