                                def _clean_default_date(date_value):
                                    """Retorna '' si es una fecha por defecto, sino retorna el valor"""
                                    default_dates = {'1900-01-01', '0001-01-01', '1900-01-01 00:00:00', '0001-01-01 00:00:00'}
                                    if not date_value:
                                        return ''
                                    date_str = str(date_value).strip()
                                    if not date_str:
                                        return ''
                                    fecha_parte = date_str.split(' ')[0] if ' ' in date_str else date_str
                                    if fecha_parte in default_dates or date_str in default_dates:
                                        return ''
                                    return date_value
                                
