                                    tk.Label(desc_box4, text="Descripción de la falla real:", bg="white",
                                        font=("Segoe UI", 8, "bold"), fg="#424242", anchor="w").pack(fill="x")
                                    desc_txt4 = tk.Text(desc_box4, height=4, wrap="word", bg="white",
                                        font=("Segoe UI", 9), relief="solid", bd=1)
