                        cur.execute(f"""
                            SELECT om.ID_ORDEN, {fecha_expr}, d.NOMBRE_ROL, u.NOMBRE_USUARIO,
                                   m.NOMBRE_MAQUINA, om.DESCRIPCION, t.NOMBRE, COALESCE(om.ESTADO, 'N'),
                                   COALESCE(tu.NOMBRE_TURNO, '') AS turno
                            FROM ORDENES om
                            LEFT JOIN DEPARTAMENTOS d ON om.ID_DEPARTAMENTO = d.ID_DEPARTAMENTO
                            LEFT JOIN USUARIOS u ON om.ID_USUARIO = u.ID_USUARIO
                            LEFT JOIN MAQUINAS m ON om.ID_MAQUINA = m.ID_MAQUINA
                            LEFT JOIN TIPOS_ORDENES t ON om.ID_TIPO = t.ID_TIPO
                            LEFT JOIN TURNOS tu ON u.ID_TURNO = tu.ID_TURNO
                            WHERE om.ID_ORDEN = ?
                        """, (oid,))
                        orden_data = cur.fetchone()
                        if not orden_data:
                            messagebox.showwarning("No encontrado", "Orden no encontrada.")
                            cur.close()
                            conn.close()
                            return
                        cur2 = conn.cursor()
                        seg_select_parts = []
                        if self.table_has_column('ORDENES_FALLAS', 'ID_JEFE_SUPERVISOR'):
                            seg_select_parts.append("COALESCE(ID_JEFE_SUPERVISOR, '') AS jefe_supervisor")
                        elif self.table_has_column('ORDENES_FALLAS', 'JEFE_SUPERVISOR'):
                            seg_select_parts.append("COALESCE(JEFE_SUPERVISOR, '') AS jefe_supervisor")
                        else:
                            seg_select_parts.append("'' AS jefe_supervisor")
                        if self.table_has_column('ORDENES_FALLAS', 'FECHA_INICIO'):
                            seg_select_parts.append("COALESCE(tm.FECHA_INICIO, '') AS inicio")
                        else:
                            seg_select_parts.append("'' AS inicio")
                        if self.table_has_column('ORDENES_FALLAS', 'FECHA_TERMINO'):
                            seg_select_parts.append("COALESCE(tm.FECHA_FIN, '') AS terminado")
                        else:
                            seg_select_parts.append("'' AS terminado")
                        if self.table_has_column('ORDENES_FALLAS', 'FECHA_ALTA'):
                            seg_select_parts.append("COALESCE(tm.FECHA_ALTA, '') AS recibido")
                        elif self.table_has_column('ORDENES_FALLAS', 'FECHA_RECIBIDO'):
                            seg_select_parts.append("COALESCE(tm.FECHA_ALTA, '') AS recibido")
                        else:
                            seg_select_parts.append("'' AS recibido")
                        if self.table_has_column('ORDENES_FALLAS', 'AREA_LIMPIA'):
                            seg_select_parts.append("COALESCE(AREA_LIMPIA, '') AS area_limpia")
                        else:
                            seg_select_parts.append("'' AS area_limpia")
                        if self.table_has_column('ORDENES_FALLAS', 'MAQUINA_LIMPIA'):
                            seg_select_parts.append("COALESCE(MAQUINA_LIMPIA, '') AS maquina_limpia")
                        else:
                            seg_select_parts.append("'' AS maquina_limpia")
                        if self.table_has_column('ORDENES_FALLAS', 'TRABAJO_SATISFACTORIO'):
                            seg_select_parts.append("COALESCE(TRABAJO_SATISFACTORIO, '') AS trabajo_satisfactorio")
                        else:
                            seg_select_parts.append("'' AS trabajo_satisfactorio")
                        seg_select_parts.append("'0' AS tiempo_muerto")
                        seg_select_parts.append("'' AS tipo_tiempo_muerto")
                        if self.table_has_column('ORDENES_FALLAS', 'ESTADO'):
                            seg_select_parts.append("COALESCE(ESTADO, '') AS seg_estado")
                        elif self.table_has_column('ORDENES_FALLAS', 'estado'):
                            seg_select_parts.append("COALESCE(estado, '') AS seg_estado")
                        else:
                            seg_select_parts.append("'' AS seg_estado")
                        # SE_UTILIZARON_REFACCIONES removed from schema — return empty
                        seg_select_parts.append("'' AS se_utilizaron_refacciones")
                        # RAZON_REFACCIONES removed from schema — return empty
                        seg_select_parts.append("'' AS razon_refacciones")
                        if self.table_has_column('ORDENES_FALLAS', 'DESCRIPCION_SOLUCION'):
                            seg_select_parts.append("COALESCE(DESCRIPCION_SOLUCION, '') AS descripcion_solucion")
                        else:
                            seg_select_parts.append("'' AS descripcion_solucion")
                        if self.table_has_column('ORDENES_FALLAS', 'OBSERVACION_FALLA'):
                            seg_select_parts.append("COALESCE(OBSERVACION_FALLA, '') AS observaciones")
                        elif self.table_has_column('ORDENES_FALLAS', 'OBSERVACIONES'):
                            seg_select_parts.append("COALESCE(OBSERVACIONES, '') AS observaciones")
                        else:
                            seg_select_parts.append("'' AS observaciones")
                        if MSSQL_AVAILABLE:
                            seg_query = """
                                SELECT TOP 1 COALESCE(u.NOMBRE_USUARIO, o.ID_JEFE_SUPERVISOR, '') AS jefe_supervisor,
                                       COALESCE(tm.FECHA_INICIO, '') AS inicio,
                                       COALESCE(tm.FECHA_FIN, '') AS terminado,
                                       COALESCE(tm.FECHA_ALTA, '') AS recibido,
                                       COALESCE(o.AREA_LIMPIA, '') AS area_limpia,
                                       COALESCE(o.MAQUINA_LIMPIA, '') AS maquina_limpia,
                                       COALESCE(o.TRABAJO_SATISFACTORIO, '') AS trabajo_satisfactorio,
                                       COALESCE(tm.MINUTOS, 0) AS tiempo_muerto,
                                       COALESCE(tm.TIPO_TIEMPO_MUERTO, '') AS tipo_tiempo_muerto,
                                       COALESCE(o.ESTADO, '') AS seg_estado,
                                       '' AS se_utilizaron_refacciones,
                                       '' AS razon_refacciones,
                                       COALESCE(t.NOMBRE, '') AS tipo_mant,
                                       '' AS descripcion_solucion,
                                       '' AS observaciones
                                FROM ORDENES_FALLAS o
                                LEFT JOIN USUARIOS u ON o.ID_JEFE_SUPERVISOR = u.ID_USUARIO
                                LEFT JOIN ORDENES ord ON o.ID_ORDEN = ord.ID_ORDEN
                                LEFT JOIN TIPOS_ORDENES t ON ord.ID_TIPO = t.ID_TIPO
                                LEFT JOIN TIEMPO_MUERTO tm ON o.ID_ORDEN = tm.ID_ORDEN AND o.ID_FALLA = tm.ID_FALLA
                                WHERE o.ID_ORDEN = ?
                            """
                        else:
                            seg_query = """
                                SELECT COALESCE(u.NOMBRE_USUARIO, o.ID_JEFE_SUPERVISOR, '') AS jefe_supervisor,
                                       COALESCE(tm.FECHA_INICIO, '') AS inicio,
                                       COALESCE(tm.FECHA_FIN, '') AS terminado,
                                       COALESCE(tm.FECHA_ALTA, '') AS recibido,
                                       COALESCE(o.AREA_LIMPIA, '') AS area_limpia,
                                       COALESCE(o.MAQUINA_LIMPIA, '') AS maquina_limpia,
                                       COALESCE(o.TRABAJO_SATISFACTORIO, '') AS trabajo_satisfactorio,
                                       COALESCE(tm.MINUTOS, 0) AS tiempo_muerto,
                                       COALESCE(tm.TIPO_TIEMPO_MUERTO, '') AS tipo_tiempo_muerto,
                                       COALESCE(o.ESTADO, '') AS seg_estado,
                                       '' AS se_utilizaron_refacciones,
                                       '' AS razon_refacciones,
                                       COALESCE(t.NOMBRE, '') AS tipo_mant,
                                       '' AS descripcion_solucion,
                                       '' AS observaciones
                                FROM ORDENES_FALLAS o
                                LEFT JOIN USUARIOS u ON o.ID_JEFE_SUPERVISOR = u.ID_USUARIO
                                LEFT JOIN ORDENES ord ON o.ID_ORDEN = ord.ID_ORDEN
                                LEFT JOIN TIPOS_ORDENES t ON ord.ID_TIPO = t.ID_TIPO
                                LEFT JOIN TIEMPO_MUERTO tm ON o.ID_ORDEN = tm.ID_ORDEN AND o.ID_FALLA = tm.ID_FALLA
                                WHERE o.ID_ORDEN = ? LIMIT 1
                            """
                        cur2.execute(seg_query, (oid,))
                        seg = cur2.fetchone()
                        cur2.close()
                        cur_fallas = conn.cursor()
                        if self.table_has_column('ORDENES_FALLAS', 'ID_JEFE_SUPERVISOR'):
                            jefe_expr = "COALESCE(uj.NOMBRE_USUARIO, ofl.ID_JEFE_SUPERVISOR, '') AS jefe_supervisor"
                            jefe_join = "LEFT JOIN USUARIOS uj ON ofl.ID_JEFE_SUPERVISOR = uj.ID_USUARIO"
                        elif self.table_has_column('ORDENES_FALLAS', 'JEFE_SUPERVISOR'):
                            jefe_expr = "COALESCE(ofl.JEFE_SUPERVISOR, '') AS jefe_supervisor"
                            jefe_join = ""
                        else:
                            jefe_expr = "'' AS jefe_supervisor"
                            jefe_join = ""

                        falla_select_parts = [
                            "ofl.ID_FALLA",
                            "COALESCE(f.DESCRIPCION, 'Sin descripción') AS nombre_falla",
                            "COALESCE(u.NOMBRE_USUARIO, ofl.ID_ATIENDE, '') AS usuario_atiende"
                        ]
                        if self.table_has_column('ORDENES_FALLAS', 'DESCRIPCION_SOLUCION'):
                            falla_select_parts.append("COALESCE(ofl.DESCRIPCION_SOLUCION, '') AS desc_sol")
                        else:
                            falla_select_parts.append("'' AS desc_sol")
                        if self.table_has_column('ORDENES_FALLAS', 'OBSERVACION_FALLA'):
                            falla_select_parts.append("COALESCE(ofl.OBSERVACION_FALLA, '') AS obs")
                        elif self.table_has_column('ORDENES_FALLAS', 'OBSERVACIONES'):
                            falla_select_parts.append("COALESCE(ofl.OBSERVACIONES, '') AS obs")
                        else:
                            falla_select_parts.append("'' AS obs")

                        # Datos adicionales por falla para refrescar la sección SOLUCIÓN Y SEGUIMIENTO
                        falla_select_parts.append(jefe_expr)
                        falla_select_parts.append("COALESCE(tm.FECHA_INICIO, '') AS inicio")
                        falla_select_parts.append("COALESCE(tm.FECHA_FIN, '') AS terminado")
                        falla_select_parts.append("COALESCE(tm.FECHA_ALTA, '') AS recibido")
                        if self.table_has_column('ORDENES_FALLAS', 'AREA_LIMPIA'):
                            falla_select_parts.append("COALESCE(ofl.AREA_LIMPIA, '') AS area_limpia")
                        else:
                            falla_select_parts.append("'' AS area_limpia")
                        if self.table_has_column('ORDENES_FALLAS', 'MAQUINA_LIMPIA'):
                            falla_select_parts.append("COALESCE(ofl.MAQUINA_LIMPIA, '') AS maquina_limpia")
                        else:
                            falla_select_parts.append("'' AS maquina_limpia")
                        if self.table_has_column('ORDENES_FALLAS', 'TRABAJO_SATISFACTORIO'):
                            falla_select_parts.append("COALESCE(ofl.TRABAJO_SATISFACTORIO, '') AS trabajo_satisfactorio")
                        else:
                            falla_select_parts.append("'' AS trabajo_satisfactorio")
                        falla_select_parts.append("COALESCE(tm.MINUTOS, 0) AS tiempo_muerto")
                        falla_select_parts.append("COALESCE(tm.TIPO_TIEMPO_MUERTO, '') AS tipo_tiempo_muerto")
                        if self.table_has_column('ORDENES_FALLAS', 'ESTADO'):
                            falla_select_parts.append("COALESCE(ofl.ESTADO, '') AS seg_estado")
                        elif self.table_has_column('ORDENES_FALLAS', 'estado'):
                            falla_select_parts.append("COALESCE(ofl.estado, '') AS seg_estado")
                        else:
                            falla_select_parts.append("'' AS seg_estado")
                        if self.table_has_column('ORDENES_FALLAS', 'RAZON'):
                            if self.table_has_column('ORDENES_FALLAS', 'MOTIVO_RAZON'):
                                falla_select_parts.append("COALESCE(ofl.RAZON, ofl.MOTIVO_RAZON, '') AS razon_falla")
                            else:
                                falla_select_parts.append("COALESCE(ofl.RAZON, '') AS razon_falla")
                        elif self.table_has_column('ORDENES_FALLAS', 'MOTIVO_RAZON'):
                            falla_select_parts.append("COALESCE(ofl.MOTIVO_RAZON, '') AS razon_falla")
                        else:
                            falla_select_parts.append("'' AS razon_falla")
                        if self.table_has_column('ORDENES_FALLAS', 'REFACCION_UTILIZADA'):
                            falla_select_parts.append("COALESCE(ofl.REFACCION_UTILIZADA, '') AS refaccion_utilizada")
                        else:
                            falla_select_parts.append("'' AS refaccion_utilizada")
                        if self.table_has_column('ORDENES_FALLAS', 'OBSERVACIONES'):
                            falla_select_parts.append("COALESCE(ofl.OBSERVACIONES, '') AS observaciones_extra")
                        else:
                            falla_select_parts.append("'' AS observaciones_extra")
                        if self.table_has_column('ORDENES_FALLAS', 'MOTIVO_FALLA'):
                            falla_select_parts.append("COALESCE(ofl.MOTIVO_FALLA, '') AS motivo_falla")
                        else:
                            falla_select_parts.append("'' AS motivo_falla")
                        if self.table_has_column('ORDENES_FALLAS', 'FALLA_REAL'):
                            falla_select_parts.append("COALESCE(ofl.FALLA_REAL, '') AS falla_real")
                        else:
                            falla_select_parts.append("'' AS falla_real")

                        falla_query = f"""
                            SELECT {', '.join(falla_select_parts)}
                            FROM ORDENES_FALLAS ofl
                            LEFT JOIN FALLAS f ON ofl.ID_FALLA = f.ID_FALLA
                            LEFT JOIN USUARIOS u ON ofl.ID_ATIENDE = u.ID_USUARIO
                            {jefe_join}
                            LEFT JOIN TIEMPO_MUERTO tm ON ofl.ID_ORDEN = tm.ID_ORDEN AND ofl.ID_FALLA = tm.ID_FALLA
                            WHERE ofl.ID_ORDEN = ?
                            ORDER BY ofl.ID_FALLA
                        """
                        cur_fallas.execute(falla_query, (oid,))
                        fallas = cur_fallas.fetchall()
                        cur_fallas.close()

                        # Resolver IDs de asignación a nombres para mostrar en "Asignado a"
                        usuarios_nombre_map = {}

                        def _parse_ids_atiende(raw_value):
                            try:
                                if raw_value is None:
                                    return []
                                txt = str(raw_value).strip()
                                if not txt:
                                    return []
                                import json
                                try:
                                    loaded = json.loads(txt)
                                    if isinstance(loaded, list):
                                        return [str(x).strip() for x in loaded if str(x).strip()]
                                    if loaded is None:
                                        return []
                                    return [str(loaded).strip()]
                                except Exception:
                                    pass
                                cleaned = txt.replace('[', '').replace(']', '').replace('"', '').replace("'", '')
                                if ',' in cleaned:
                                    return [p.strip() for p in cleaned.split(',') if p.strip()]
                                return [txt]
                            except Exception:
                                return []

                        try:
                            ids_all = []
                            for falla in fallas:
                                raw_atiende = falla[2] if len(falla) > 2 else ''
                                for uid in _parse_ids_atiende(raw_atiende):
                                    if uid and uid not in ids_all:
                                        ids_all.append(uid)

                            if ids_all:
                                cur_usr = conn.cursor()
                                placeholders = ','.join(['%s'] * len(ids_all))
                                cur_usr.execute(
                                    f"SELECT CAST(ID_USUARIO AS CHAR), COALESCE(NOMBRE_USUARIO, '') FROM USUARIOS WHERE CAST(ID_USUARIO AS CHAR) IN ({placeholders})",
                                    tuple(ids_all)
                                )
                                for _uid, _uname in cur_usr.fetchall() or []:
                                    key = str(_uid).strip() if _uid is not None else ''
                                    if key:
                                        usuarios_nombre_map[key] = str(_uname).strip() if _uname else ''
                                cur_usr.close()
                        except Exception:
                            usuarios_nombre_map = {}

                        def _resolver_asignado(raw_value):
                            ids = _parse_ids_atiende(raw_value)
                            if not ids:
                                return ''
                            nombres = []
                            for _id in ids:
                                nombres.append(usuarios_nombre_map.get(_id) or _id)
                            return ', '.join(nombres)

                        conn.close()
