                        title_label.pack(side="left", padx=20, pady=(14, 4))
                        order_num_label = tk.Label(header_frame, text=f"N° {oid}", 
                                                  bg="#5b7a9c", fg="#e8ecf1", font=("Segoe UI", 14, "bold"))
                        order_num_label.pack(side="left", padx=12, pady=(14, 4))
                        falla_selector_var = tk.StringVar(value="")
