                                main_frame.pack(fill="both", expand=True, padx=10, pady=10)
                                canvas = tk.Canvas(main_frame, bg="#e0e0e0", highlightthickness=0)
                                scrollbar = ttk.Scrollbar(main_frame, orient="vertical", command=canvas.yview)
                                scrollable_frame = tk.Frame(canvas, bg="#e0e0e0")
                                scrollable_frame.bind(
                                    "<Configure>",
                                    lambda e: canvas.configure(scrollregion=canvas.bbox("all"))
                                )
                                canvas.create_window((0, 0), window=scrollable_frame, anchor="nw")
                                canvas.configure(yscrollcommand=scrollbar.set)
                                canvas.pack(side="left", fill="both", expand=True)
                                scrollbar.pack(side="right", fill="y")
                                def _on_mousewheel(event):
                                    canvas.yview_scroll(int(-1*(event.delta/120)), "units")
                                canvas.bind_all("<MouseWheel>", _on_mousewheel)
                                prev_win.bind("<MouseWheel>", _on_mousewheel)
                                content_frame = tk.Frame(scrollable_frame, bg="white", relief="solid", bd=2)
                                content_frame.pack(padx=10, pady=10, fill="both", expand=True)
                                inner_frame = tk.Frame(content_frame, bg="white")
