                                        sol_text = tk.Text(falla_frame, height=2, width=100, bg="#f5f7fa", font=("Segoe UI", 7), bd=0, wrap="word")
                                        sol_text.pack(fill="both", expand=True, padx=15, pady=(1, 2))
