                                "COALESCE(tm.MINUTOS, 0) AS tiempo_muerto" if self.table_has_column('ORDENES_FALLAS', 'TIEMPO_MUERTO_MIN') else "0 AS tiempo_muerto",
                                "COALESCE(tm.TIPO_TIEMPO_MUERTO, '') AS tipo_tiempo_muerto" if self.table_has_column('ORDENES_FALLAS', 'TIPO_TIEMPO_MUERTO') else "'' AS tipo_tiempo_muerto",
