                            _fi_col = 'INICIO' if self.table_has_column('ORDENES_FALLAS','INICIO') else ('FECHA_INICIO' if self.table_has_column('ORDENES_FALLAS','FECHA_INICIO') else None)
                            _ft_col = 'TERMINADO' if self.table_has_column('ORDENES_FALLAS','TERMINADO') else ('FECHA_TERMINO' if self.table_has_column('ORDENES_FALLAS','FECHA_TERMINO') else None)
                            _fo_col = 'OBSERVACIONES' if self.table_has_column('ORDENES_FALLAS','OBSERVACIONES') else ('OBSERVACION_FALLA' if self.table_has_column('ORDENES_FALLAS','OBSERVACION_FALLA') else None)
                            _fa_col = 'AREA_LIMPIA' if self.table_has_column('ORDENES_FALLAS','AREA_LIMPIA') else ('ALEAR_LIMPIA' if self.table_has_column('ORDENES_FALLAS','ALEAR_LIMPIA') else None)
                            _seg_exprs = [
                                "COALESCE(of.SOLUCION,'') AS f_solucion" if self.table_has_column('ORDENES_FALLAS','SOLUCION') else "'' AS f_solucion",
                                "COALESCE(of.DESCRIPCION_SOLUCION,'') AS f_desc_sol" if self.table_has_column('ORDENES_FALLAS','DESCRIPCION_SOLUCION') else "'' AS f_desc_sol",
                                f"COALESCE(of.{_fo_col},'') AS f_observ" if _fo_col else "'' AS f_observ",
                                "COALESCE(of.JEFE_SUPERVISOR,'') AS f_jefe" if self.table_has_column('ORDENES_FALLAS','JEFE_SUPERVISOR') else "'' AS f_jefe",
                                "COALESCE(ofl.RECIBIO,'') AS f_recibio" if self.table_has_column('ORDENES_FALLAS','RECIBIO') else "'' AS f_recibio",
                                f"COALESCE(ofl.{_fi_col},'') AS f_inicio" if _fi_col else "'' AS f_inicio",
                                f"COALESCE(ofl.{_ft_col},'') AS f_terminado" if _ft_col else "'' AS f_terminado",
                                "COALESCE(ofl.RECIBIDO,'') AS f_recibido" if self.table_has_column('ORDENES_FALLAS','RECIBIDO') else "'' AS f_recibido",
                                f"COALESCE(ofl.{_fa_col},'') AS f_area_limpia" if _fa_col else "'' AS f_area_limpia",
                                "COALESCE(ofl.MAQUINA_LIMPIA,'') AS f_maq_limpia" if self.table_has_column('ORDENES_FALLAS','MAQUINA_LIMPIA') else "'' AS f_maq_limpia",
                                "COALESCE(ofl.TRABAJO_SATISFACTORIO,'') AS f_trabajo" if self.table_has_column('ORDENES_FALLAS','TRABAJO_SATISFACTORIO') else "'' AS f_trabajo",
                                "COALESCE(tm.MINUTOS,0) AS f_tmuerto" if self.table_has_column('ORDENES_FALLAS','TIEMPO_MUERTO_MIN') else "0 AS f_tmuerto",
                                "COALESCE(ofl.TIPO_TIEMPO_MUERTO,'') AS f_tipo_tm" if self.table_has_column('ORDENES_FALLAS','TIPO_TIEMPO_MUERTO') else "'' AS f_tipo_tm",
                            ]
                            cur_fallas.execute(f"""
                                SELECT ofl.ID_FALLA, COALESCE(f.DESCRIPCION, 'Sin descripción') AS NOMBRE_FALLA,
                                       COALESCE(ofl.ID_ATIENDE, '') AS ID_ATIENDE,
                                       {', '.join(_seg_exprs)}
                                FROM ORDENES_FALLAS ofl
                                LEFT JOIN FALLAS f ON ofl.ID_FALLA = f.ID_FALLA
                                LEFT JOIN TIEMPO_MUERTO tm ON ofl.ID_ORDEN = tm.ID_ORDEN AND ofl.ID_FALLA = tm.ID_FALLA
                                WHERE ofl.ID_ORDEN = ?
                                ORDER BY ofl.ID_FALLA
                            """, (oid,))
                            fallas_asignaciones_raw = cur_fallas.fetchall()
                            for raw_row in fallas_asignaciones_raw:
                                falla_id     = raw_row[0]
                                falla_nombre = raw_row[1]
                                id_atiende   = raw_row[2]
                                seg_data = {
                                    'solucion':             raw_row[3],
                                    'descripcion_solucion': raw_row[4],
                                    'observaciones':        raw_row[5],
                                    'jefe_supervisor':      raw_row[6],
                                    'recibio':              raw_row[7],
                                    'inicio':               raw_row[8],
                                    'terminado':            raw_row[9],
                                    'recibido':             raw_row[10],
                                    'area_limpia':          raw_row[11],
                                    'maquina_limpia':       raw_row[12],
                                    'trabajo_satisfactorio': raw_row[13],
                                    'tiempo_muerto':        raw_row[14],
                                    'tipo_tiempo_muerto':   raw_row[15],
                                }
                                usuarios_asignados = []
                                if id_atiende:
                                    try:
                                        import json
                                        try:
                                            usuarios_ids = json.loads(id_atiende)
                                        except (json.JSONDecodeError, ValueError):
                                            usuarios_ids = [int(id_atiende)] if str(id_atiende).isdigit() else []
                                        if usuarios_ids:
                                            placeholders = ','.join(['?'] * len(usuarios_ids))
                                            cur_usuarios = conn.cursor()
                                            cur_usuarios.execute(f"SELECT NOMBRE_USUARIO FROM USUARIOS WHERE ID_USUARIO IN ({placeholders})", tuple(usuarios_ids))
                                            usuarios_asignados = [u[0] for u in cur_usuarios.fetchall()]
                                            cur_usuarios.close()
                                    except Exception:
                                        usuarios_asignados = []
                                fallas_asignaciones.append((falla_id, falla_nombre, usuarios_asignados, seg_data))
                            cur_fallas.close()
