                        def _parse_time_parts(value):
                            if not value:
                                return '', ''
                            try:
                                from datetime import datetime
                                if isinstance(value, datetime):
                                    return value.strftime('%H'), value.strftime('%M')
                                text = str(value).strip()
                                if not text:
                                    return '', ''
                                if ' ' in text:
                                    text = text.split(' ')[1]
                                parts = text.split(':')
                                if len(parts) >= 2:
                                    return parts[0][:2], parts[1][:2]
                            except Exception:
                                pass
                            return '', ''
                        
