                        def normalize_si_no(value):
                            """Convierte valores de la BD (S, N, Si, No, Y, 1, etc.) a 'Si' o 'No'"""
                            if value is None or value == '':
                                return 'No'
                            val_str = str(value).strip().upper()
                            if val_str in ('SI', 'S', 'Y', 'YES', '1', 'TRUE', 'VERDADERO'):
                                return 'Si'
                            return 'No'
                        
