                        def _read_time_parts(hour_var, minute_var):
                            hour = str(hour_var.get()).strip() if hour_var is not None else ''
                            minute = str(minute_var.get()).strip() if minute_var is not None else ''
                            if not (hour and minute):
                                return None
                            if not (hour.isdigit() and minute.isdigit()):
                                return None
                            try:
                                hour_int = int(hour)
                                minute_int = int(minute)
                                if 0 <= hour_int <= 23 and 0 <= minute_int <= 59:
                                    return hour_int, minute_int
                            except Exception:
                                pass
                            return None
