                            query_fallas = f"SELECT {', '.join(cols)} FROM ORDENES_FALLAS ord_fal LEFT JOIN FALLAS f ON ord_fal.ID_FALLA = f.ID_FALLA LEFT JOIN TIEMPO_MUERTO tm ON ord_fal.ID_ORDEN = tm.ID_ORDEN AND ord_fal.ID_FALLA = tm.ID_FALLA WHERE ord_fal.ID_ORDEN = ? ORDER BY ord_fal.ID_FALLA ASC"
