        populate_tab_refacciones()
        populate_tab_ordenes()
        def populate_tab_herramientas():
            """Poblar pestaña de Herramientas / Equipo."""
            for w in tab_herramientas.winfo_children():
                w.destroy()
            header = tk.Frame(tab_herramientas, bg=self.card_bg, padx=8, pady=8)
            header.pack(fill="x")
            tk.Label(header, text="Herramientas / Equipo", font=("Segoe UI", 12, "bold"), bg=self.card_bg).pack(side="left")
            tv_frame = tk.Frame(tab_herramientas, bg=self.card_bg)
            tv_frame.pack(fill="both", expand=True, padx=8, pady=8)
            tv_herr = ttk.Treeview(tv_frame, columns=("orden","solicitud","solicita","turno","titulo","descripcion"), show="headings")
            tv_herr.heading("orden", text="ORDEN")
            tv_herr.heading("solicitud", text="SOLICITUD")
            tv_herr.heading("solicita", text="SOLICITA")
            tv_herr.heading("turno", text="TURNO")
            tv_herr.heading("titulo", text="TÚTULO")
            tv_herr.heading("descripcion", text="DESCRIPCIÓN")
            tv_herr.column("orden", width=80, anchor="center", stretch=False)
            tv_herr.column("solicitud", width=120, anchor="center", stretch=False)
            tv_herr.column("solicita", width=120, stretch=True)
            tv_herr.column("turno", width=80, anchor="center", stretch=False)
            tv_herr.column("titulo", width=180, stretch=True)
            tv_herr.column("descripcion", width=250, stretch=True)
            tv_herr.pack(fill="both", expand=True, side="left")
            scr = ttk.Scrollbar(tv_frame, orient="vertical", command=tv_herr.yview)
            scr.pack(side="right", fill="y")
            tv_herr.configure(yscroll=scr.set)
            def load_herramientas():
                for item in tv_herr.get_children():
                    tv_herr.delete(item)
                try:
                    cfg = {"host": DB_SERVER, "user": DB_USER, "password": DB_PASSWORD, "database": DB_NAME}
                    conn = mysql.connect(**cfg)
                    cur = conn.cursor()
                    fecha_col = self.get_ordenes_fecha_column()
                    fecha_select = fecha_col if fecha_col else "NULL"
                    fecha_order = fecha_col if fecha_col else "ID_ORDEN"
                    if self.table_has_column('ORDENES', 'OTRO_TIPO'):
                        cur.execute(f"""
                            SELECT ID_ORDEN, {fecha_select} AS FECHA_SOLICITUD, ID_USUARIO, DESCRIPCION
                            FROM ORDENES
                            WHERE OTRO_TIPO = %s
                            ORDER BY {fecha_order} DESC
                        """, ("Herramientas / Equipo",))
                    else:
                        cur.execute(f"""
                            SELECT ID_ORDEN, {fecha_select} AS FECHA_SOLICITUD, ID_USUARIO, DESCRIPCION
                            FROM ORDENES
                            WHERE DESCRIPCION LIKE %s
                            ORDER BY {fecha_order} DESC
                        """, ("%Herramientas / Equipo%",))
                    rows = cur.fetchall()
                    cur.close()
                    conn.close()
                    for row in rows:
                        id_orden, fecha, solicita_id, descripcion = row
                        titulo = (descripcion[:120] if descripcion else "")
                        solicita_nombre = str(solicita_id)
                        try:
                            cfg = {"host": DB_SERVER, "user": DB_USER, "password": DB_PASSWORD, "database": DB_NAME}
                            conn = mysql.connect(**cfg)
                            cur = conn.cursor()
                            cur.execute("SELECT nombre_usuario FROM usuarios WHERE id_usuario = %s", (solicita_id,))
                            result = cur.fetchone()
                            solicita_nombre = result[0] if result else str(solicita_id)
                            cur.close()
                            conn.close()
                        except Exception:
                            pass
                        turno_num = ""
                        fecha_str = fecha.strftime("%d/%m/%Y") if hasattr(fecha, 'strftime') else str(fecha)
                        tv_herr.insert("", "end", values=(id_orden, fecha_str, solicita_nombre, turno_num, titulo or "", descripcion or ""))
                except Exception as e:
                    print(f"Error cargando Herramientas: {e}")
            load_herramientas()
