    def get_machines_by_department(self, id_departamento):
        """Retorna lista de (id_maquina, nombre_maquina) para un departamento dado."""
        try:
            cfg = {"host": DB_SERVER, "user": DB_USER, "password": DB_PASSWORD, "database": DB_NAME}
            conn = mysql.connect(**cfg)
            cur = conn.cursor()
            # Detectar si el usuario actual debe ver todas las máquinas
            is_admin_flag = getattr(self, 'is_admin', False)
            is_admin_login = getattr(self, 'is_admin_login', False)
            dep_name = (getattr(self, 'current_dep_name', '') or '')
            is_admin_by_dep = isinstance(dep_name, str) and ('administr' in dep_name.lower())
            try:
                log_debug(f"get_machines_by_department: id_departamento={id_departamento} is_admin={is_admin_flag} is_admin_login={is_admin_login} dep_name='{dep_name}'")
            except Exception:
                pass
            # Si es administrador por cualquiera de los flags o se pidió sin departamento, devolver todas
            if is_admin_flag or is_admin_login or is_admin_by_dep or id_departamento in (None, 0):
                cur.execute("SELECT ID_MAQUINA, NOMBRE_MAQUINA FROM MAQUINAS ORDER BY NOMBRE_MAQUINA")
            else:
                cur.execute("SELECT ID_MAQUINA, NOMBRE_MAQUINA FROM MAQUINAS WHERE ID_DEPARTAMENTO=%s AND ESTADO='A' ORDER BY NOMBRE_MAQUINA", (id_departamento,))
            rows = cur.fetchall()
            cur.close()
            conn.close()
            return rows
        except Exception:
            return []
    def create_user_db(self, nombre, login, pwd, id_departamento, estado, cargo=None, nivel=None, id_turno=None, max_retries=3):
        """Inserta un usuario en la BD con reintentos ante deadlocks/lock wait timeouts.
        Devuelve True si la inserción fue exitosa, False si agotó reintentos.
        Lanza la excepción para errores distintos a lock wait timeout.
        """
        cfg = {"host": DB_SERVER, "user": DB_USER, "password": DB_PASSWORD, "database": DB_NAME}
        try:
            conn_temp = mysql.connect(**cfg)
            cur_temp = conn_temp.cursor()
            cur_temp.execute("SELECT MAX(CAST(SUBSTRING(ID_USUARIO, 5, LEN(ID_USUARIO)) AS INT)) FROM usuarios WHERE ID_USUARIO LIKE 'USU_%'")
            result = cur_temp.fetchone()
            max_num = result[0] if result and result[0] else 0
            user_id = f"USU_{max_num + 1:05d}"
            cur_temp.close()
            conn_temp.close()
        except Exception as e:
            import time
            user_id = f"USU_{int(time.time()) % 100000:05d}"
        attempt = 0
        while attempt < max_retries:
            conn = None
            cur = None
            try:
                conn = mysql.connect(**cfg)
                conn.autocommit = False
                cur = conn.cursor()
                # Asegurar que id_departamento no sea NULL (la columna en la BD no admite NULL).
                # Para administradores creamos/aseguramos un departamento genérico '0000' y lo usamos.
                if id_departamento is None:
                    try:
                        # Intentar insertar departamento genérico si no existe
                        cur.execute("IF NOT EXISTS (SELECT 1 FROM DEPARTAMENTOS WHERE ID_DEPARTAMENTO = '0000') INSERT INTO DEPARTAMENTOS (ID_DEPARTAMENTO, NOMBRE_ROL) VALUES ('0000','Administración')")
                    except Exception:
                        try:
                            conn.rollback()
                        except Exception:
                            pass
                    id_departamento_to_insert = '0000'
                else:
                    id_departamento_to_insert = id_departamento
                columns = ["ID_USUARIO", "nombre_usuario", "usuario_login", "password_hash", "id_departamento", "estado", "cargo"]
                values = [user_id, nombre, login, pwd, id_departamento_to_insert, estado, cargo]
                if self.table_has_column('usuarios', 'FECHA_CREACION') or self.table_has_column('usuarios', 'fecha_creacion'):
                    columns.append("fecha_creacion")
                    values.append(datetime.now())
                if self.table_has_column('usuarios', 'ID_TURNO'):
                    columns.append("ID_TURNO")
                    values.append(id_turno)
                if nivel is not None and self.table_has_column('usuarios', 'nivel'):
                    columns.append("nivel")
                    values.append(nivel)
                placeholders = ",".join(["%s"] * len(values))
                sql = f"INSERT INTO usuarios ({', '.join(columns)}) VALUES ({placeholders})"
                cur.execute(sql, tuple(values))
                conn.commit()
                return True
            except Exception as e:
                msg = str(e)
                errno = getattr(e, 'errno', None)
                if errno == 1205 or 'Lock wait timeout' in msg or 'lock wait timeout' in msg.lower():
                    attempt += 1
                    try:
                        if conn:
                            conn.rollback()
                    except Exception:
                        pass
                    wait = 0.5 * (2 ** (attempt - 1))
                    time.sleep(wait)
                    continue
                else:
                    try:
                        if conn:
                            conn.rollback()
                    except Exception:
                        pass
                    raise
            finally:
                try:
                    if cur:
                        cur.close()
                except Exception:
                    pass
                try:
                    if conn:
                        conn.close()
                except Exception:
                    pass
        return False
    def check_for_new_orders(self):
        """Verifica si hay nuevas órdenes desde el último check."""
        try:
            cfg = {"host": DB_SERVER, "user": DB_USER, "password": DB_PASSWORD, "database": DB_NAME}
            conn = mysql.connect(**cfg)
            cur = conn.cursor()
            fecha_col = self.get_ordenes_fecha_column()
            max_expr = fecha_col if fecha_col else "ID_ORDEN"
            cur.execute(f"SELECT MAX({max_expr}) FROM ORDENES")
            result = cur.fetchone()
            cur.close()
            conn.close()
            last_order_time = result[0] if result and result[0] else None
            if last_order_time and self.new_orders_notification["last_check"]:
                if last_order_time > self.new_orders_notification["last_check"]:
                    return True
            elif last_order_time and not self.new_orders_notification["last_check"]:
                self.new_orders_notification["last_check"] = last_order_time
            return False
        except Exception as e:
            print(f"Error al verificar órdenes nuevas: {e}")
            return False
